/* ================================================================
   Account Maintenance Module CSS - Moved to Global Styles
   These styles are used throughout the application for form layouts,
   kairo composite controls, and standardized form field styling.
================================================================ */

:root {
    --primary: var(--copilot-primary, #3c53e8);
    --primary-dark: var(--copilot-primary-hover, #357ABD);
    --secondary: var(--kairo-form-actions-bg, #F5F7FA);
    --border: var(--kairo-border-color, #DDE6ED);
    --text-dark: var(--copilot-text-main, #2C3E50);
    --text-gray: var(--copilot-text-muted, #5A6C7D);
    --text-light: #8B98A5;
    --white: #FFFFFF;
    --success: #27AE60;
    --warning: #F39C12;
    --danger: #E74C3C;
    --info: #3498DB;
    --radius: 3px;
    --shadow-sm: 0 6px 16px rgba(44, 62, 80, 0.06);
    --transition: all 0.2s ease;
    --title-bar-height: 22px;
}

/* Window and Layout */
.window {
    background: var(--kairo-form-canvas-bg, #F5F6F8);
    border: none;
    border-radius: 0;
    box-shadow: none;
    max-width: none;
    margin: 0;
    position: relative;
    overflow: hidden;
    min-height: 100vh;
}

    /* Glassmorphism Container Wrapper */
    .window::before {
        content: "";
        position: absolute;
        top: 0;
        left: 0;
        right: 0;
        bottom: 0;
        background: rgba(255, 255, 255, 0.03);
        backdrop-filter: none;
        -webkit-backdrop-filter: none;
        pointer-events: none;
        z-index: 0;
    }

    /* Maximized state - hide sidebar and extend form */
    .window.maximized {
        width: 100%;
    }

        .window.maximized .sidebar {
            display: none !important;
        }

        .window.maximized .main-container {
            --sidebar-width: 0 !important;
            gap: 0 !important;
            padding: 0 !important;
            width: 100%;
            flex: 1;
        }

.form-content-without-leftbar {
    margin-left: 10px;
}

.window.maximized .form-content {
    width: 100%;
    min-width: 100%;
}

.title-bar {
    background: linear-gradient(180deg, var(--color-header) 0%, var(--color-header) 100%);
    color: #ffffff;
    padding: 10px 16px;
    display: flex;
    justify-content: space-between;
    align-items: center;
    min-height: 40px;
    border-bottom: none;
    position: relative;
    z-index: 10;
}

.title-bar-left {
    display: flex;
    align-items: center;
    gap: 10px;
}

.title-icon {
    font-size: 16px;
    color: #ffffff;
}

.title-text {
    font-weight: 600;
    font-size: 14px;
    color: #ffffff;
}

.title-bar-right {
    display: flex;
    gap: 6px;
}

.title-btn {
    background: rgba(255, 255, 255, 0.15);
    border: 1px solid rgba(255, 255, 255, 0.25);
    color: #ffffff;
    width: 28px;
    height: 26px;
    border-radius: 4px;
    cursor: pointer;
    font-size: 12px;
    transition: var(--transition);
    line-height: 1;
    display: flex;
    align-items: center;
    justify-content: center;
}

    .title-btn:hover {
        background: rgba(255, 255, 255, 0.25);
        border-color: rgba(255, 255, 255, 0.4);
    }

    .title-btn.close:hover {
        background: #dc2626;
        border-color: #dc2626;
    }

    .title-btn.refresh {
        font-size: 13px;
    }

/* Main Container */
.main-container {
    display: flex;
    background: transparent;
    position: relative;
    isolation: isolate;
    z-index: 1;
    --sidebar-width: clamp(200px, 20vw, 280px);
    --sidebar-collapsed-width: clamp(52px, 8vw, 68px);
    --action-panel-width: clamp(110px, 10vw, 150px);
    gap: clamp(6px, 1vw, 12px);
    padding: clamp(4px, 0.8vw, 10px);
    min-height: calc(100vh - var(--title-bar-height));
    box-shadow: -2px 0 8px rgba(37, 99, 235, 0.1);
}

    /* Main container without sidebar - form content uses full width */
    .main-container.main-container--no-sidebar .form-content {
        flex: 1 1 100%;
        min-width: 0;
    }

/* Sidebar */
.sidebar {
    width: var(--sidebar-width);
    background: linear-gradient(180deg, #ffffff 0%, #f8fafc 100%);
    border-right: 2px solid #e2e8f0;
    padding: 12px;
    overflow-y: auto;
    height: calc(100vh - var(--title-bar-height));
    transition: width 0.3s ease, filter 0.3s ease;
    box-shadow: inset -1px 0 0 rgba(0, 0, 0, 0.05);
}

/* Subtle blur on sidebar when form is open */
.window .sidebar {
    filter: blur(0px);
}

.window.form-open .sidebar {
    opacity: 0.8;
}

/* SUBMODULES Header */
.sidebar-header {
    margin-bottom: 16px;
    padding-bottom: 12px;
    border-bottom: 2px solid #e2e8f0;
    display: flex;
    justify-content: space-between;
    align-items: center;
    position: relative;
    background: linear-gradient(180deg, #ffffff 0%, #f8fafc 100%);
    padding-top: 4px;
    border-radius: 6px 6px 0 0;
}

.sidebar-header__title {
    display: flex;
    align-items: center;
    gap: 8px;
    font-size: 12px;
    font-weight: 700;
    color: var(--color-text, var(--color-text-primary, #1e293b));
    text-transform: uppercase;
    letter-spacing: 0.8px;
}

    .sidebar-header__title i {
        font-size: 14px;
        color: var(--color-header, var(--color-primary, #4a7c95));
    }

.sidebar-toggle {
    background: var(--color-header, var(--color-primary, #4a7c95));
    border: 1px solid var(--color-header, var(--color-primary, #4a7c95));
    border-radius: 4px;
    width: 32px;
    height: 32px;
    display: flex !important;
    align-items: center;
    justify-content: center;
    cursor: pointer;
    color: white;
    font-size: 18px;
    padding: 0;
    transition: all 0.2s ease;
    flex-shrink: 0;
    z-index: 100;
}

    .sidebar-toggle i {
        font-size: 18px;
    }

    .sidebar-toggle:hover {
        background: var(--primary-dark, color-mix(in srgb, var(--color-header, var(--color-primary, #4a7c95)) 85%, black 15%));
        border-color: var(--primary-dark, color-mix(in srgb, var(--color-header, var(--color-primary, #4a7c95)) 85%, black 15%));
        color: white;
    }

.sidebar.collapsed {
    width: var(--sidebar-collapsed-width);
    min-width: var(--sidebar-collapsed-width);
    overflow: visible;
    padding: 8px 4px;
}

    /* Hide text elements when collapsed */
    .sidebar.collapsed .sidebar-header__title span:not(.bi),
    .sidebar.collapsed .sidebar-search,
    .sidebar.collapsed .nav-label--card,
    .sidebar.collapsed .nav-badge,
    .sidebar.collapsed .sidebar-item__text,
    .sidebar.collapsed .nav-header__badge,
    .sidebar.collapsed .nav-header__content span {
        display: none !important;
    }

    /* Always show toggle button when collapsed */
    .sidebar.collapsed .sidebar-toggle {
        display: flex !important;
        visibility: visible !important;
        opacity: 1 !important;
        position: relative !important;
        z-index: 1000 !important;
        margin: 0 !important;
        width: 36px !important;
        height: 36px !important;
        background: var(--color-header, var(--color-primary, #4a7c95)) !important;
        border-color: var(--color-header, var(--color-primary, #4a7c95)) !important;
        color: white !important;
        font-size: 18px !important;
        flex-shrink: 0 !important;
        cursor: pointer !important;
    }

