}

.nav-header__icon {
    font-size: 17px;
    color: var(--color-header, var(--color-primary, #4a7c95));
}

.nav-label--card {
    font-size: 13px;
    font-weight: 600;
    color: var(--color-text, var(--color-text-primary, #1e293b));
    padding: 0;
    letter-spacing: 0.2px;
}

.nav-header__badge {
    display: flex;
    align-items: center;
    gap: 8px;
    padding-right: 14px;
}

.nav-badge {
    display: inline-flex;
    align-items: center;
    justify-content: center;
    min-width: 24px;
    height: 24px;
    padding: 0 7px;
    background: linear-gradient(180deg, var(--color-header, var(--color-primary, #4a7c95)) 0%, color-mix(in srgb, var(--color-header, var(--color-primary, #4a7c95)) 85%, black 15%) 100%);
    color: #fff;
    border-radius: 12px;
