    }

.nav-label {
    flex: 1;
    padding: 7px 10px;
    user-select: none;
    display: flex;
    align-items: center;
    font-size: 10px;
    font-weight: 600;
    color: rgba(255, 255, 255, 0.85);
}

.nav-arrow {
    width: 30px;
    height: 30px;
    border: none;
    border-left: 1px solid rgba(255, 255, 255, 0.28);
