    width: 22px;
    text-align: center;
}

.sidebar-item__text {
    flex: 1;
    min-width: 0;
    overflow: hidden;
}

.sidebar-item__title {
    font-size: 13px;
    font-weight: 600;
    color: var(--color-text, var(--color-text-primary, #1e293b));
