    }

.sidebar-item i {
    font-size: 12px;
    color: var(--text-light);
}

.nav-label i {
    font-size: 12px;
    color: rgba(255, 255, 255, 0.80);
}

.sidebar-item.sidebar-item--static:hover {
    color: var(--text-dark);
    background: transparent;
}

/* Form Content */
.form-content {
    flex: 1;
    /*padding: 16px 20px; */
    background: rgba(255, 255, 255, 0.08);
    overflow-y: auto;
    height: calc(100vh - var(--title-bar-height));
    scroll-behavior: smooth;
}

    /* Form Section Cards */
    .form-content > .section-header:first-of-type {
        margin-top: 0;
    }

    /* Add subtle card effect to form sections */
    .form-content > .form-row:first-of-type {
        margin-top: 0;
    }

/* 4-Column Grid Layout (Account Maintenance Style) */
.kairo-grid-4 {
    display: grid;
    grid-template-columns: repeat(4, 1fr);
    gap: 16px;
    margin-bottom: 20px;
}

.kairo-field {
    display: flex;
    flex-direction: column;
    gap: 6px;
    min-width: 0;
    /* Prevent overflow */
}

    .kairo-field label {
        font-size: 11px;
        font-weight: 600;
        color: var(--color-text, var(--color-text-primary, #1e293b));
        margin-bottom: 0;
    }

    /* Ensure all inputs within grid fields are same size */
    .kairo-field input[type="text"],
    .kairo-field input[type="date"],
    .kairo-field input[type="number"],
    .kairo-field select,
    .kairo-field textarea {
        width: 100% !important;
        max-width: none !important;
        box-sizing: border-box;
    }

    /* Ensure product control fits grid */
    .kairo-field .kairo-product-control {
        width: 100%;
        max-width: none;
    }

    /* Ensure flex containers with buttons don't overflow */
    .kairo-field > div[style*="display: flex"] {
        width: 100%;
        max-width: none;
    }

/* Responsive - 2 columns on medium screens */
@media (max-width: 1200px) {
    .kairo-grid-4 {
        grid-template-columns: repeat(2, 1fr);
    }
}

/* Responsive - 1 column on small screens */
@media (max-width: 768px) {
    .kairo-grid-4 {
        grid-template-columns: 1fr;
    }
}

/* Child form overlay */
.child-overlay {
    position: absolute;
    top: 0;
    right: 0;
    bottom: 0;
    left: var(--sidebar-width);
    display: none;
    padding: 12px;
    background: rgba(44, 62, 80, 0.18);
    z-index: 999;
    transition: left 0.3s ease;
}

.main-container.sidebar-collapsed .child-overlay {
    left: var(--sidebar-collapsed-width);
}

.child-overlay.is-open {
    display: flex;
}

.child-frame {
    flex: 1;
    min-width: 0;
    min-height: 0;
    border: 1px solid rgba(255, 255, 255, 0.3);
    border-radius: var(--radius);
    background: rgba(245, 246, 248, 0.85);
    backdrop-filter: blur(10px);
    -webkit-backdrop-filter: blur(10px);
    box-shadow: 0 8px 24px rgba(0, 0, 0, 0.1);
    overflow: hidden;
    width: 100%;
    height: 100%;
}

.child-iframe {
    width: 100%;
    height: 100%;
    border: none;
    display: block;
    background: transparent;
}



/* Disbursement Schedule Entry (DSE) - Data Entry Module Layout */
.dse-shell {
    display: flex;
    flex-direction: row;
    height: 100%;
    gap: 0;
    overflow: hidden;
}

.dse-body {
    display: flex;
    flex-direction: row;
    width: 100%;
    height: 100%;
    gap: 0;
    overflow: hidden;
}

.dse-content {
    flex: 1;
    min-width: 0;
    display: flex;
    flex-direction: column;
    overflow-y: auto;
    overflow-x: hidden;
    padding: 12px;
}

.dse-actions {
    width: 120px;
    min-width: 120px;
    display: flex;
    flex-direction: column;
    background: rgba(245, 246, 248, 0.5);
    border-left: 1px solid rgba(74, 144, 226, 0.2);
    padding: 8px;
    gap: 4px;
}

.dse-actions__stack {
    display: flex;
    flex-direction: column;
    gap: 4px;
    height: 100%;
}

.dse-action-btn {
    flex: 1;
    min-height: 36px;
    border: 1px solid var(--color-border);
    border-radius: var(--radius);
    background-color: #f8f9fa;
    color: #333;
    font-size: 12px;
    font-weight: 500;
    cursor: pointer;
    transition: all 0.2s ease;
    white-space: nowrap;
    overflow: hidden;
    text-overflow: ellipsis;
    padding: 6px 8px;
}

    .dse-action-btn:hover:not(:disabled) {
        background-color: #e9ecef;
        border-color: rgba(74, 144, 226, 0.4);
    }

    .dse-action-btn:active:not(:disabled) {
        background-color: #dee2e6;
    }

    .dse-action-btn:disabled {
        opacity: 0.5;
        cursor: not-allowed;
    }

.dse-action-btn--primary {
    background-color: var(--color-primary);
    color: #ffffff;
    border-color: var(--color-primary);
    font-weight: 600;
}

    .dse-action-btn--primary:hover:not(:disabled) {
        background-color: var(--color-primary);
        opacity: 0.85;
        border-color: var(--color-primary);
    }

    .dse-action-btn--primary:active:not(:disabled) {
        opacity: 0.7;
    }

/* Form Row and Labels */
.form-row {
    display: flex;
    align-items: flex-start;
    gap: 12px;
    margin-bottom: 12px;
    transition: all 0.2s ease;
}

    .form-row:hover {
        background: rgba(74, 144, 226, 0.02);
        border-radius: 4px;
    }

/* Form row hover micro-interaction (padding/margin) – only when theme setting is enabled */
body.form-row-hover-on .form-row:hover {
    padding: 2px 4px;
    margin-left: -4px;
    margin-right: -4px;
}

/* Labels in columns should be above controls */
.col label {
    display: block;
    margin-bottom: 4px;
    font-size: 12px;
    color: var(--text-gray);
    font-weight: 500;
    transition: color 0.2s ease;
}

.form-row:hover .col label {
    color: #333;
}

.label-blue,
[class*="label--blue"],
span.label-blue,
span[class*="label--blue"] {
    color: var(--color-label-mandatory, #2563eb) !important;
    font-family: var(--label-font-family) !important;
    font-size: var(--label-font-size) !important;
    font-weight: var(--label-font-weight) !important;
}

    /* Span elements inside .label-blue labels */
    .label-blue span:not(.required):not([class*="required"]):not(.bts-info-btn):not([class*="info"]),
    [class*="label--blue"] span:not(.required):not([class*="required"]):not(.bts-info-btn):not([class*="info"]) {
        color: var(--color-label-mandatory, #2563eb) !important;
        font-family: var(--label-font-family) !important;
        font-size: var(--label-font-size) !important;
        font-weight: var(--label-font-weight) !important;
    }

    /* Remove asterisks from blue labels */
    .label-blue::after,
    [class*="label--blue"]::after {
        display: none !important;
        content: '' !important;
    }

/* Bootstrap row/col patterns - compact layout */
.row.g-2 {
    --bs-gutter-x: 0.75rem;
    --bs-gutter-y: 0.5rem;
}

.row.mb-2 {
    margin-bottom: 0.5rem !important;
}

/* Ensure labels in Bootstrap columns are above controls */
.row .col-6 label,
.row .col-12 label {
