/* Passbook Serial ID sizing */
#PassbookSerialID {
    width: 170px;
    max-width: 170px;
}

    #PassbookSerialID + .btn-lookup {
        width: 22px;
        height: 22px;
        padding: 0;
        font-size: 11px;
    }

.checkbox {
    width: 14px;
    height: 14px;
}

/* Two Column Layout */
.form-row.two-col {
    display: flex;
    gap: 16px;
    margin-top: 12px;
    margin-bottom: 12px;
}

    .form-row.two-col .col {
        flex: 1;
        min-width: 0;
    }

        .form-row.two-col .col > label {
            display: block;
            margin-bottom: 4px;
            font-size: 11px;
            font-weight: 600;
        }

        .form-row.two-col .col label {
            font-size: 11px;
            font-weight: 600;
            text-align: left;
        }

        .form-row.two-col .col input,
