/* Three Column Layout */
.form-row.three-col {
    display: grid;
    grid-template-columns: repeat(3, 1fr);
    gap: 16px;
    margin-top: 12px;
    margin-bottom: 12px;
}

    .form-row.three-col .col[style*="span 3"],
    .form-row.three-col .col.span-3 {
