        flex-direction: column !important;
        gap: 6px !important;
        min-width: 0 !important;
        width: 100% !important;
        align-items: flex-start !important;
    }

        .form-row.five-col .col label {
            font-size: 11px;
            color: #1a5276;
            font-weight: 600;
        }

        .form-row.five-col .col input,
        .form-row.five-col .col select,
        .form-row.five-col .col textarea {
