/* ============================================================================
   SUBMODULE MODAL STYLING - Covers main form area, leaves sidebar visible
   Used for loan-application, account-maintenance, and other modules with sidebars
   ============================================================================ */

/* Define CSS variable for submodule modal offset */
:root {
    --submodule-modal-left: 250px;
    /* Default: expanded sidebar width */
}

/* Dynamic sidebar width tracking */
.main-container:has(.sidebar:not(.collapsed)) ~ .submodule-modal,
body:has(.sidebar:not(.collapsed)) .submodule-modal {
    --submodule-modal-left: 250px;
}

.main-container:has(.sidebar.collapsed) ~ .submodule-modal,
body:has(.sidebar.collapsed) .submodule-modal {
    --submodule-modal-left: 56px;
}

/* When sidebar is hidden (maximized window or no sidebar) */
.window.maximized .submodule-modal,
body:has(.window.maximized) .submodule-modal,
body:not(:has(.sidebar)) .submodule-modal {
    --submodule-modal-left: 0px;
}

.submodule-modal {
    position: fixed !important;
    top: 0 !important;
    left: var(--submodule-modal-left, 250px) !important;
    right: 0 !important;
    bottom: 0 !important;
    width: calc(100% - var(--submodule-modal-left, 250px)) !important;
    z-index: 1055 !important;
    /* Above action-panel */
    background: transparent;
    display: none;
}

/* Hide action panel when submodule modal is open */
body.modal-open .action-panel {
    z-index: 1050;
    /* Below submodule-modal */
}

.submodule-modal.show {
    display: block !important;
}

/* Modal dialog fills the available space with spacing */
.submodule-modal .modal-dialog {
    position: relative;
    margin: 12px;
    max-width: calc(100% - 24px);
    width: calc(100% - 24px);
    height: calc(100% - 24px);
    display: flex;
    align-items: stretch;
}

.submodule-modal .modal-content {
    width: 100%;
    height: 100%;
    border: 1px solid rgba(0, 0, 0, 0.1);
    border-radius: 8px;
    background: #f4f8f9;
    display: flex;
    flex-direction: column;
    box-shadow: 0 8px 32px rgba(0, 0, 0, 0.2);
    overflow: hidden;
}

/* When parent window is maximized - more spacing and centered */
.window.maximized .submodule-modal .modal-dialog,
body:has(.window.maximized) .submodule-modal .modal-dialog {
    margin: 20px;
    max-width: calc(100% - 40px);
    width: calc(100% - 40px);
    height: calc(100% - 40px);
}

.submodule-modal .modal-content iframe {
    width: 100%;
    height: 100%;
    border: none;
    flex: 1;
}

/* Override Bootstrap modal backdrop for submodule modals */
.submodule-modal ~ .modal-backdrop,
.submodule-modal + .modal-backdrop {
    display: none !important;
}

/* Ensure sidebar remains visible when modal is open */
body.modal-open .sidebar {
    z-index: 1040;
}

/* Kairo search modal backdrop - higher z-index */
.kairo-search-modal ~ .modal-backdrop,
.kairo-search-modal + .modal-backdrop {
    z-index: 1055 !important;
}

