        color: #2c3e50;
    }

    .am-card .list-group-item.active {
        background-color: #dbeafe;
        color: #1e40af;
        border-left: 4px solid #3b82f6;
        font-weight: 600;
    }

    .am-card .list-group-item i {
        margin-right: 0.5rem;
    }

/* Theme Sections */
.am-card .theme-section {
    animation: fadeIn 0.3s ease;
}

    .am-card .theme-section[style*="display: none"] {
        display: none !important;
    }

@keyframes fadeIn {
    from {
        opacity: 0;
        transform: translateY(-5px);
    }

    to {
        opacity: 1;
        transform: translateY(0);
    }
}

/* Color Controls */
.am-card .theme-color-control {
    display: flex;
    align-items: center;
    gap: 0.5rem;
    flex-wrap: wrap;
}

.am-card .theme-color-input {
    width: 60px;
    height: 42px;
    border: 2px solid #dee2e6;
    border-radius: 4px;
    cursor: pointer;
    flex-shrink: 0;
    transition: border-color 0.2s ease, box-shadow 0.2s ease;
    padding: 2px;
}

    .am-card .theme-color-input:hover {
        border-color: #999;
        box-shadow: 0 0 8px rgba(0, 0, 0, 0.12);
    }

    .am-card .theme-color-input:focus {
        outline: 2px solid #0066cc;
        outline-offset: 2px;
        border-color: #0066cc;
    }

    .am-card .theme-color-input:active {
        transform: scale(0.98);
    }

.am-card .color-value-display {
    flex: 0 0 100px;
    font-family: monospace;
    font-size: 0.9rem;
    text-transform: uppercase;
}

/* ============================================
   BEHIND THE SCENE - Card-Based Layout
   ============================================ */

/* Card Grid Container */
.bts-card-grid {
    display: grid;
    grid-template-columns: repeat(auto-fit, minmax(320px, 1fr));
    gap: 1.25rem;
    padding: 1rem 0;
}

@media (min-width: 992px) {
    .bts-card-grid {
        grid-template-columns: repeat(2, 1fr);
    }
}

@media (min-width: 1400px) {
    .bts-card-grid {
        grid-template-columns: repeat(3, 1fr);
    }
}

/* Individual Card */
.bts-card {
    background: #fafbfc;
    border: 1px solid #e4e7eb;
    border-radius: 8px;
    padding: 1.25rem;
    transition: border-color 0.2s ease, box-shadow 0.15s ease;
}

    .bts-card:hover {
        border-color: #d1d5db;
        box-shadow: 0 2px 8px rgba(0, 0, 0, 0.04);
    }

/* Card Title */
.bts-card__title {
    font-size: 0.75rem;
    font-weight: 600;
    color: #64748b;
    text-transform: uppercase;
    letter-spacing: 0.05em;
    margin: 0 0 1rem 0;
    padding-bottom: 0.5rem;
    border-bottom: 1px solid #e4e7eb;
}

/* Card Content */
.bts-card__content {
    display: flex;
    flex-direction: column;
    gap: 0.875rem;
}

/* Field Container */
.bts-field {
    display: flex;
    flex-direction: column;
    gap: 0.25rem;
}

.bts-field--compact {
    gap: 0.15rem;
}

.bts-field--highlight {
    padding: 0.5rem;
    background: #f8f9fa;
    border-radius: 4px;
    border-left: 3px solid #3b82f6;
}

/* Label */
.bts-label {
    font-size: 0.688rem;
    font-weight: 500;
    color: #6b7280;
    text-transform: uppercase;
    letter-spacing: 0.03em;
    line-height: 1.3;
    margin: 0;
    padding: 0;
}

/* Value */
.bts-value {
    font-size: 1rem;
    font-weight: 600;
    color: #1f2937;
    line-height: 1.5;
    word-break: break-word;
    padding: 0;
    margin: 0;
    background: transparent;
    border: none;
    display: block;
}

/* Value Variants */
.bts-value--primary {
    font-size: 1.125rem;
    font-weight: 700;
    color: var(--color-text, var(--color-text-primary, #0f172a));
}

.bts-value--small {
    font-size: 0.875rem;
    font-weight: 500;
    color: #4b5563;
}

.bts-value--money,
.bts-value--percent {
    text-align: right;
    font-family: 'Courier New', Consolas, monospace;
    font-variant-numeric: tabular-nums;
}

.bts-value--date {
    font-family: 'Courier New', Consolas, monospace;
    font-size: 0.9rem;
}

.bts-value--status {
    display: inline-flex;
    align-items: center;
    padding: 0.25rem 0.75rem;
    border-radius: 12px;
    font-size: 0.813rem;
    font-weight: 600;
    background: #e5e7eb;
    color: #374151;
    width: fit-content;
    text-transform: capitalize;
}

    /* Status Color Variants */
    .bts-value--status[data-status="active"],
    .bts-value--status:is([id*="Status"]):not(:empty):not([data-status]) {
        background: #d1fae5;
        color: #065f46;
    }

    .bts-value--status[data-status="inactive"] {
        background: #fee2e2;
        color: #991b1b;
    }

    .bts-value--status[data-status="dormant"] {
        background: #fef3c7;
        color: #92400e;
    }

    .bts-value--status[data-status="closed"] {
        background: #e5e7eb;
        color: #4b5563;
    }

/* Empty State */
.bts-value:empty::before,
.bts-value:is(:not(:empty)):has(br)::before {
    content: '—';
    color: #9ca3af;
    font-style: italic;
}

/* Responsive Adjustments */
@media (max-width: 768px) {
    .bts-card-grid {
        grid-template-columns: 1fr;
        gap: 1rem;
    }

    .bts-card {
        padding: 1rem;
    }

    .bts-value--primary {
        font-size: 1rem;
    }
}

