    .reminder-modal__body {
        padding: 1.5rem;
        min-height: 80px;
    }

    .reminder-modal__message {
        font-size: 0.9875rem;
        line-height: 1.6;
    }

    .reminder-modal__footer {
        padding: 1.25rem 1.5rem 1.75rem 1.5rem;
        justify-content: center;
    }

    .reminder-modal__button {
        width: 100%;
        padding: 0.75rem 1.5rem;
        font-size: 0.875rem;
    }
}

@media (max-width: 991px) {
    .am-card .theme-color-control {
        flex-direction: column;
        align-items: stretch;
    }

    .am-card .theme-color-input {
        width: 100%;
    }

    .am-card .color-value-display {
        flex: 1;
    }
}

/* ============================================================================
   MESSAGE BAR / TOAST NOTIFICATIONS
   ============================================================================ */
.de-message-bar {
    display: none;
    align-items: center;
    gap: 8px;
    padding: 10px 16px;
    font-size: 13px;
    background: #fef3c7;
    border-top: 2px solid #fcd34d;
    color: #92400e;
    flex-shrink: 0;
    transition: all 0.3s ease;
}

    .de-message-bar.show {
        display: flex;
    }

    .de-message-bar.error {
        background: #fee2e2;
        border-color: #ef4444;
        color: #991b1b;
    }

    .de-message-bar.success {
        background: #d1fae5;
        border-color: #10b981;
        color: #065f46;
    }

    .de-message-bar.info {
        background: #dbeafe;
        border-color: #3b82f6;
        color: #1e40af;
    }

    .de-message-bar.warning {
        background: #fef3c7;
        border-color: #fcd34d;
        color: #92400e;
    }

    .de-message-bar i {
        font-size: 16px;
        flex-shrink: 0;
    }

    .de-message-bar span {
        flex: 1;
    }

.de-message-bar__close,
.am-message-panel__close {
    flex-shrink: 0;
    padding: 4px;
    margin: -4px 0 -4px 8px;
    background: none;
    border: none;
    color: inherit;
    opacity: 0.85;
    cursor: pointer;
    border-radius: 4px;
    line-height: 1;
}

    .de-message-bar__close:hover,
    .am-message-panel__close:hover {
        opacity: 1;
    }

    .de-message-bar__close:focus,
    .am-message-panel__close:focus {
        outline: 1px solid currentColor;
        outline-offset: 2px;
    }

/* ============================================================================
   STATUS BAR
   ============================================================================ */
.de-status-bar {
    background: #f8fafc;
    border-top: 1px solid #e2e8f0;
    padding: 4px 12px;
    font-size: 11px;
    color: #64748b;
    flex-shrink: 0;
    height: 22px;
}

/* ============================================================================
   LOADING OVERLAY
   ============================================================================ */
.de-loading-overlay {
    position: fixed;
    top: 0;
    left: 0;
    right: 0;
    bottom: 0;
    background: rgba(0, 0, 0, 0.5);
    display: flex;
    align-items: center;
    justify-content: center;
    z-index: 9999;
}

    .de-loading-overlay[hidden] {
        display: none;
    }

.de-loading-spinner {
    display: flex;
    flex-direction: column;
    align-items: center;
    gap: 12px;
    background: white;
    padding: 24px 32px;
    border-radius: 8px;
    box-shadow: 0 4px 6px rgba(0, 0, 0, 0.1);
}

    .de-loading-spinner i {
        font-size: 32px;
        color: var(--color-primary, #4a7c95);
        animation: spin 1s linear infinite;
    }

    .de-loading-spinner span {
        font-size: 14px;
        color: #64748b;
    }

@keyframes spin {
    from {
        transform: rotate(0deg);
    }

    to {
        transform: rotate(360deg);
    }
}

/* ============================================================================
   VALIDATION SUMMARY (Account Maintenance Standard)
   Inline alert banner for form validation and messages
   ============================================================================ */
.validation-summary {
    background: color-mix(in srgb, #ffffff 92%, #ef4444 8%);
    border: 1px solid color-mix(in srgb, #ef4444 30%, #ffffff 70%);
    border-radius: 6px;
    padding: 10px 14px;
    margin-bottom: 14px;
    display: none;
    align-items: center;
    gap: 10px;
    animation: fadeInSummary 0.25s ease;
}

    .validation-summary.is-visible {
        display: flex;
    }

.validation-summary__icon {
    color: color-mix(in srgb, #ef4444 70%, #000000 30%);
    font-size: 16px;
    flex-shrink: 0;
}

.validation-summary__text {
    font-size: 12px;
    color: color-mix(in srgb, #ef4444 65%, #000000 35%);
    line-height: 1.4;
    flex: 1;
}

/* Close button for validation summary */
.validation-summary__close {
    background: transparent;
    border: none;
    color: color-mix(in srgb, #ef4444 65%, #000000 35%);
    font-size: 16px;
    cursor: pointer;
    padding: 0 4px;
    margin-left: auto;
    flex-shrink: 0;
    opacity: 0.7;
    transition: opacity 0.15s ease;
}

    .validation-summary__close:hover {
        opacity: 1;
    }

.validation-summary--success .validation-summary__close {
    color: color-mix(in srgb, #10b981 75%, #000000 25%);
}

/* Success variant of validation summary */
.validation-summary--success {
    background: color-mix(in srgb, #ffffff 94%, #10b981 6%);
    border-color: color-mix(in srgb, #10b981 35%, #ffffff 65%);
}

    .validation-summary--success .validation-summary__icon {
        color: color-mix(in srgb, #10b981 75%, #000000 25%);
    }

    .validation-summary--success .validation-summary__text {
        color: color-mix(in srgb, #10b981 70%, #000000 30%);
    }

@keyframes fadeInSummary {
    from {
        opacity: 0;
        transform: translateY(-4px);
    }

    to {
        opacity: 1;
        transform: translateY(0);
    }
}

/* Hide summary when no errors */
.validation-summary:empty,
.validation-summary:not(.is-visible) {
    display: none;
}

/* ============================================================================
   CASH TRANSACTION OVERLAY STYLES
   Supports: Modal Overlay backdrop, Drawer (right slide), Modal Centered
   ============================================================================ */

/* MODAL OVERLAY BACKDROP */
.modal-overlay {
    position: fixed;
    inset: 0;
    background: rgba(15, 23, 42, 0.5);
    backdrop-filter: blur(2px);
    z-index: 1040;
    opacity: 0;
    visibility: hidden;
    transition: opacity 0.2s ease, visibility 0.2s ease;
}

    .modal-overlay.visible {
        opacity: 1;
        visibility: visible;
    }

body.overlay-open {
    overflow: hidden;
}

/* DRAWER (Right Slide Panel) */
.drawer-right {
    position: fixed;
    top: 0;
    right: 0;
    height: 100vh;
    width: 420px;
    max-width: 90vw;
    background: #fff;
    box-shadow: -4px 0 24px rgba(0, 0, 0, 0.15);
    z-index: 1050;
    display: flex;
    flex-direction: column;
    transform: translateX(100%);
    transition: transform 0.3s cubic-bezier(0.4, 0, 0.2, 1);
}

    .drawer-right.visible {
        transform: translateX(0);
    }

.drawer-right--wide {
    width: 520px;
}

.drawer-right__header {
    display: flex;
    align-items: center;
    justify-content: space-between;
    padding: 16px 20px;
    background: linear-gradient(135deg, #1e3a5f 0%, #2563eb 100%);
    color: #fff;
    flex-shrink: 0;
}

.drawer-right__title {
    margin: 0;
    font-size: 16px;
    font-weight: 600;
    display: flex;
    align-items: center;
    gap: 8px;
}

    .drawer-right__title i {
        font-size: 18px;
        opacity: 0.9;
    }

.drawer-right__close {
    background: rgba(255, 255, 255, 0.15);
    border: none;
    color: #fff;
    width: 32px;
    height: 32px;
    border-radius: 6px;
    cursor: pointer;
    display: flex;
    align-items: center;
    justify-content: center;
    transition: background 0.15s ease;
}

    .drawer-right__close:hover {
        background: rgba(255, 255, 255, 0.25);
    }

.drawer-right__body {
    flex: 1;
    overflow-y: auto;
    padding: 20px;
}

.drawer-right__footer {
    padding: 12px 20px;
    background: #f8fafc;
    border-top: 1px solid #e2e8f0;
    display: flex;
    gap: 8px;
    justify-content: flex-end;
    flex-shrink: 0;
}

/* MODAL CENTERED */
.modal-centered {
    position: fixed;
    top: 50%;
    left: 50%;
    transform: translate(-50%, -50%) scale(0.95);
    background: #fff;
    border-radius: 12px;
    box-shadow: 0 20px 60px rgba(0, 0, 0, 0.2);
    z-index: 1050;
    width: 500px;
    max-width: 90vw;
    max-height: 90vh;
    display: flex;
    flex-direction: column;
    opacity: 0;
    visibility: hidden;
    transition: opacity 0.2s ease, transform 0.2s ease, visibility 0.2s ease;
}

    .modal-centered.visible {
        opacity: 1;
        visibility: visible;
        transform: translate(-50%, -50%) scale(1);
    }

.modal-centered--wide {
    width: 900px;
    max-width: 95vw;
}

.modal-centered--signature {
    width: 700px;
}

.modal-centered--teller {
    width: 600px;
}

.modal-centered--denomination {
    width: 400px;
}

.modal-centered--print {
    width: 450px;
}

.modal-centered__header {
    display: flex;
    align-items: center;
    justify-content: space-between;
    padding: 16px 20px;
    background: linear-gradient(135deg, #1e3a5f 0%, #2563eb 100%);
    color: #fff;
    border-radius: 12px 12px 0 0;
    flex-shrink: 0;
}

.modal-centered__title {
    margin: 0;
    font-size: 16px;
    font-weight: 600;
    display: flex;
    align-items: center;
    gap: 8px;
}

    .modal-centered__title i {
        font-size: 18px;
        opacity: 0.9;
    }

.modal-centered__close {
    background: rgba(255, 255, 255, 0.15);
    border: none;
    color: #fff;
    width: 32px;
    height: 32px;
    border-radius: 6px;
    cursor: pointer;
    display: flex;
    align-items: center;
    justify-content: center;
    transition: background 0.15s ease;
}

    .modal-centered__close:hover {
        background: rgba(255, 255, 255, 0.25);
    }

.modal-centered__body {
    flex: 1;
    overflow-y: auto;
    padding: 20px;
}

.modal-centered__footer {
    padding: 12px 20px;
    background: #f8fafc;
    border-top: 1px solid #e2e8f0;
    border-radius: 0 0 12px 12px;
    display: flex;
    gap: 8px;
    justify-content: flex-end;
    flex-shrink: 0;
}

/* DETAIL SECTIONS (Inside Drawer) */
.detail-section {
    margin-bottom: 20px;
    padding-bottom: 16px;
    border-bottom: 1px solid #e2e8f0;
}

    .detail-section:last-child {
        border-bottom: none;
        margin-bottom: 0;
    }

.detail-section__title {
    font-size: 13px;
    font-weight: 600;
    color: #1e3a5f;
    margin: 0 0 12px;
    display: flex;
    align-items: center;
    gap: 6px;
}

.detail-section__title--blue {
    color: #2563eb;
}

.detail-section__title i {
    font-size: 14px;
}

.detail-row {
    display: flex;
    justify-content: space-between;
    align-items: center;
    padding: 6px 0;
    font-size: 13px;
}

.detail-row__label {
    color: #64748b;
}

.detail-row__value {
    font-weight: 500;
    color: var(--color-text, var(--color-text-primary, #1e293b));
}

/* SIGNATORY GRID */
.signatory-grid-wrap {
    overflow-x: auto;
    border: 1px solid #e2e8f0;
    border-radius: 8px;
}

.signatory-grid {
    width: 100%;
    border-collapse: collapse;
    font-size: 12px;
}

    .signatory-grid thead {
        background: #f1f5f9;
    }

    .signatory-grid th,
    .signatory-grid td {
        padding: 8px 10px;
        text-align: left;
        border-bottom: 1px solid #e2e8f0;
    }

    .signatory-grid th {
        font-weight: 600;
        color: #475569;
        font-size: 11px;
        text-transform: uppercase;
    }

    .signatory-grid tbody tr {
        cursor: pointer;
        transition: background 0.15s ease;
    }

        .signatory-grid tbody tr:hover {
            background: #f8fafc;
        }

        .signatory-grid tbody tr.selected {
            background: #dbeafe;
        }

.signatory-grid__empty td {
    text-align: center;
    color: #94a3b8;
    padding: 20px;
}

/* MEDIA GRID (Signature/Photo/Document cards) */
.media-grid {
    display: grid;
    grid-template-columns: repeat(3, 1fr);
    gap: 12px;
}

.media-card {
    border: 1px solid #e2e8f0;
    border-radius: 8px;
    overflow: hidden;
    display: flex;
    flex-direction: column;
}

.media-card__label {
    background: #f8fafc;
    padding: 6px 10px;
    font-size: 11px;
    font-weight: 600;
    color: #64748b;
    text-transform: uppercase;
    border-bottom: 1px solid #e2e8f0;
}

.media-card__preview {
    height: 100px;
    display: flex;
    align-items: center;
    justify-content: center;
    background: #fff;
}

    .media-card__preview img {
        max-width: 100%;
        max-height: 100%;
        object-fit: contain;
    }

.media-card__placeholder {
    display: flex;
    flex-direction: column;
    align-items: center;
    gap: 4px;
    color: #cbd5e1;
}

    .media-card__placeholder i {
        font-size: 28px;
    }

    .media-card__placeholder span {
        font-size: 10px;
    }

.media-card__zoom {
    border: none;
    background: #f1f5f9;
    padding: 6px;
    font-size: 11px;
    color: #2563eb;
    cursor: pointer;
    display: flex;
    align-items: center;
    justify-content: center;
    gap: 4px;
    transition: background 0.15s ease;
}

    .media-card__zoom:hover {
        background: #e2e8f0;
    }

/* BALANCE GRID */
.balance-grid {
    display: grid;
    grid-template-columns: repeat(2, 1fr);
    gap: 10px;
}

.balance-grid--full {
    grid-template-columns: repeat(3, 1fr);
}

.balance-card {
    background: #f8fafc;
    border: 1px solid #e2e8f0;
    border-radius: 6px;
    padding: 10px 12px;
}

.balance-card__label {
    display: block;
    font-size: 11px;
    color: #64748b;
    margin-bottom: 4px;
}

.balance-card__value {
    display: block;
    font-size: 14px;
    font-weight: 600;
    color: var(--color-text, var(--color-text-primary, #1e293b));
}

.balance-card--highlight {
    background: linear-gradient(135deg, #dbeafe 0%, #eff6ff 100%);
    border-color: #93c5fd;
}

    .balance-card--highlight .balance-card__value {
        color: #1d4ed8;
    }

/* TELLER MODAL */
.teller-summary {
    display: grid;
    grid-template-columns: repeat(2, 1fr);
    gap: 12px;
    margin-bottom: 20px;
}

.teller-card {
    background: #f8fafc;
    border: 1px solid #e2e8f0;
    border-radius: 8px;
    padding: 12px 16px;
    text-align: center;
}

.teller-card__label {
    display: block;
    font-size: 11px;
    color: #64748b;
    margin-bottom: 4px;
    text-transform: uppercase;
}

.teller-card__value {
    display: block;
    font-size: 18px;
    font-weight: 700;
    color: var(--color-text, var(--color-text-primary, #1e293b));
}

.teller-card--credit {
    background: #dcfce7;
    border-color: #86efac;
}

    .teller-card--credit .teller-card__value {
        color: #166534;
    }

.teller-card--debit {
    background: #fee2e2;
    border-color: #fca5a5;
}

    .teller-card--debit .teller-card__value {
        color: #991b1b;
    }

.teller-card--highlight {
    background: linear-gradient(135deg, #1e3a5f 0%, #2563eb 100%);
    border-color: transparent;
}

    .teller-card--highlight .teller-card__label {
        color: rgba(255, 255, 255, 0.8);
    }

    .teller-card--highlight .teller-card__value {
        color: #fff;
    }

.teller-table-wrap {
    border: 1px solid #e2e8f0;
    border-radius: 8px;
    overflow: hidden;
    max-height: 300px;
    overflow-y: auto;
}

.teller-table {
    width: 100%;
    border-collapse: collapse;
    font-size: 12px;
}

    .teller-table thead {
        background: #f1f5f9;
        position: sticky;
        top: 0;
    }

    .teller-table th,
    .teller-table td {
        padding: 8px 12px;
        text-align: left;
        border-bottom: 1px solid #e2e8f0;
    }

    .teller-table th {
        font-weight: 600;
        color: #475569;
        font-size: 11px;
        text-transform: uppercase;
    }

    .teller-table tbody tr:hover {
        background: #f8fafc;
    }

.teller-table__empty td {
    text-align: center;
    color: #94a3b8;
    padding: 30px;
}

/* VIEW ALL TRANSACTIONS MODAL */
.trx-grid-wrap {
    border: 1px solid #e2e8f0;
    border-radius: 8px;
    overflow: hidden;
    max-height: 400px;
    overflow-y: auto;
}

.trx-grid-table {
    width: 100%;
    border-collapse: collapse;
    font-size: 11px;
    white-space: nowrap;
}

    .trx-grid-table thead {
        background: #1e3a5f;
        position: sticky;
        top: 0;
    }

    .trx-grid-table th {
        padding: 10px 12px;
        text-align: left;
        font-weight: 600;
        color: #fff;
        font-size: 10px;
        text-transform: uppercase;
    }

    .trx-grid-table td {
        padding: 8px 12px;
        border-bottom: 1px solid #e2e8f0;
    }

    .trx-grid-table tbody tr {
        cursor: pointer;
        transition: background 0.15s ease;
    }

        .trx-grid-table tbody tr:hover {
            background: #f1f5f9;
        }

        .trx-grid-table tbody tr.selected {
            background: #dbeafe;
        }

.trx-grid-table__empty td {
    text-align: center;
    color: #94a3b8;
    padding: 40px;
}

.trx-grid-status {
    flex: 1;
    font-size: 12px;
    color: #64748b;
}

/* DENOMINATION MODAL */
.denomination-grid {
    border: 1px solid #e2e8f0;
    border-radius: 8px;
    overflow: hidden;
}

.denomination-table {
    width: 100%;
    border-collapse: collapse;
    font-size: 13px;
}

    .denomination-table thead {
        background: #f1f5f9;
    }

    .denomination-table th,
    .denomination-table td {
        padding: 10px 14px;
        border-bottom: 1px solid #e2e8f0;
    }

    .denomination-table th {
        font-weight: 600;
        color: #475569;
        text-align: left;
    }

    .denomination-table td:first-child {
        font-weight: 600;
        color: var(--color-text, var(--color-text-primary, #1e293b));
    }

.denom-count {
    width: 80px;
    padding: 6px 10px;
    border: 1px solid #cbd5e1;
    border-radius: 4px;
    font-size: 13px;
    text-align: center;
}

    .denom-count:focus {
        outline: none;
        border-color: #2563eb;
        box-shadow: 0 0 0 2px rgba(37, 99, 235, 0.2);
    }

.denom-amount {
    font-weight: 500;
    color: var(--color-text, var(--color-text-primary, #1e293b));
}

.denomination-total {
    background: #1e3a5f;
    color: #fff;
}

    .denomination-total td {
        border-bottom: none;
        padding: 12px 14px;
    }

/* PRINT PREVIEW MODAL */
.print-preview-body {
    background: #f1f5f9;
    padding: 20px;
}

.print-content {
    background: #fff;
    border: 1px solid #e2e8f0;
    border-radius: 4px;
    padding: 24px;
    max-width: 350px;
    margin: 0 auto;
    font-family: 'Segoe UI', sans-serif;
}

.receipt-header {
    text-align: center;
    margin-bottom: 16px;
    padding-bottom: 12px;
    border-bottom: 2px solid #1e3a5f;
}

    .receipt-header h2 {
        margin: 0;
        font-size: 16px;
        color: #1e3a5f;
    }

    .receipt-header p {
        margin: 4px 0 0;
        font-size: 12px;
        color: #64748b;
    }

.receipt-details {
    font-size: 12px;
}

.receipt-row {
    display: flex;
    justify-content: space-between;
    padding: 4px 0;
}

.receipt-label {
    color: #64748b;
}

.receipt-value {
    font-weight: 500;
    color: var(--color-text, var(--color-text-primary, #1e293b));
}

.receipt-amount .receipt-value {
    font-size: 16px;
    font-weight: 700;
    color: #1e3a5f;
}

.receipt-details hr {
    border: none;
    border-top: 1px dashed #cbd5e1;
    margin: 10px 0;
}

.receipt-footer {
    text-align: center;
    margin-top: 16px;
    padding-top: 12px;
    border-top: 1px solid #e2e8f0;
    font-size: 10px;
    color: #94a3b8;
}

    .receipt-footer p {
        margin: 2px 0;
    }

/* SIGNATURE MODAL */
.modal-tabs {
    display: flex;
    border-bottom: 1px solid #e2e8f0;
    background: #f8fafc;
}

.modal-tab {
    flex: 1;
    padding: 10px 16px;
    border: none;
    background: transparent;
    font-size: 12px;
    font-weight: 500;
    color: #64748b;
    cursor: pointer;
    display: flex;
    align-items: center;
    justify-content: center;
    gap: 6px;
    transition: all 0.15s ease;
}

    .modal-tab:hover {
        background: #e2e8f0;
        color: var(--color-text, var(--color-text-primary, #1e293b));
    }

    .modal-tab.active {
        background: #fff;
