/* ================================================================
   Global Glassmorphism Styles for Form Elements
   Production-grade frosted glass effect for all inputs and selects
================================================================ */

/* Base glassmorphism for all standard HTML form inputs */
input[type="text"],
input[type="email"],
input[type="password"],
input[type="tel"],
input[type="url"],
input[type="search"],
input[type="number"],
input[type="date"],
input[type="datetime-local"],
input[type="month"],
input[type="week"],
input[type="time"],
select,
textarea {
    height: var(--bs-input-height, 48px);
    padding: var(--bs-input-padding, 12px 14px);
    border: 1px solid var(--glass-border, rgba(255, 255, 255, 0.3));
    border-radius: var(--bs-input-radius, 4px);
    background: var(--glass-bg, rgba(255, 255, 255, 0.15));
    box-shadow: var(--glass-shadow, 0 4px 10px rgba(0, 0, 0, 0.05));
    color: var(--kairo-text-color, var(--bs-input-text, #2C3E50));
    font-family: var(--kairo-font-family, "Segoe UI", Tahoma, Arial, sans-serif);
    font-size: var(--bs-input-font-size, 10px);
    font-weight: var(--bs-input-font-weight, 800);
    transition: background 0.3s ease, border-color 0.3s ease, box-shadow 0.3s ease, outline 0.2s ease;
    outline: 2px solid transparent;
    outline-offset: 2px;
}

/* Textarea specific - auto height */
textarea {
    height: auto;
    min-height: 80px;
    resize: vertical;
}

/* Select specific - cursor */
select {
    cursor: pointer;
}

    /* Hover states for all form elements */
    input[type="text"]:hover,
    input[type="email"]:hover,
    input[type="password"]:hover,
    input[type="tel"]:hover,
    input[type="url"]:hover,
    input[type="search"]:hover,
    input[type="number"]:hover,
    input[type="date"]:hover,
    input[type="datetime-local"]:hover,
    input[type="month"]:hover,
    input[type="week"]:hover,
    input[type="time"]:hover,
    select:hover,
    textarea:hover {
        background: var(--glass-bg-hover, rgba(255, 255, 255, 0.22));
        border-color: var(--glass-border-hover, rgba(255, 255, 255, 0.45));
        box-shadow: var(--glass-shadow-hover, 0 6px 14px rgba(0, 0, 0, 0.08));
    }

    /* Focus states with visible blue outline ring */
    input[type="text"]:focus,
    input[type="email"]:focus,
    input[type="password"]:focus,
    input[type="tel"]:focus,
    input[type="url"]:focus,
    input[type="search"]:focus,
    input[type="number"]:focus,
    input[type="date"]:focus,
    input[type="datetime-local"]:focus,
    input[type="month"]:focus,
    input[type="week"]:focus,
    input[type="time"]:focus,
    select:focus,
    textarea:focus {
        background: var(--glass-bg-hover, rgba(255, 255, 255, 0.22));
        border-color: var(--glass-focus-ring, #3b82f6);
        box-shadow: var(--glass-shadow-hover, 0 6px 14px rgba(0, 0, 0, 0.08));
        outline: 2px solid var(--color-primary, #3b82f6);
        outline-offset: 2px;
    }

    /* Focus-visible for keyboard navigation */
    input[type="text"]:focus-visible,
    input[type="email"]:focus-visible,
    input[type="password"]:focus-visible,
    input[type="tel"]:focus-visible,
    input[type="url"]:focus-visible,
    input[type="search"]:focus-visible,
    input[type="number"]:focus-visible,
    input[type="date"]:focus-visible,
    input[type="datetime-local"]:focus-visible,
    input[type="month"]:focus-visible,
    input[type="week"]:focus-visible,
    input[type="time"]:focus-visible,
    select:focus-visible,
    textarea:focus-visible {
        outline: 2px solid var(--color-primary, #3b82f6);
        outline-offset: 2px;
    }

    /* Disabled state - reduced opacity, preserve glass effect */
    input:disabled,
    select:disabled,
    textarea:disabled {
        cursor: not-allowed;
        background: var(--glass-bg, rgba(255, 255, 255, 0.15));
    }

/* Read-only state */
input:read-only:not([type="checkbox"]):not([type="radio"]),
textarea:read-only {
    background: rgba(255, 255, 255, 0.08);
    cursor: default;
}

/* Placeholder styling */
input::placeholder,
textarea::placeholder {
    color: rgba(44, 62, 80, 0.5);
    font-weight: 400;
}

/* Autofill styling - maintain glass effect */
input:-webkit-autofill,
input:-webkit-autofill:hover,
input:-webkit-autofill:focus,
select:-webkit-autofill,
select:-webkit-autofill:hover,
select:-webkit-autofill:focus,
textarea:-webkit-autofill,
textarea:-webkit-autofill:hover,
textarea:-webkit-autofill:focus {
    -webkit-box-shadow: 0 0 0 1000px rgba(255, 255, 255, 0.2) inset, var(--glass-shadow, 0 4px 10px rgba(0, 0, 0, 0.05));
    -webkit-text-fill-color: var(--kairo-text-color, #2C3E50);
    transition: background-color 5000s ease-in-out 0s;
}

/* File input specific styling */
input[type="file"] {
    padding: 10px 14px;
    cursor: pointer;
}

    input[type="file"]::file-selector-button {
        background: var(--glass-bg-hover, rgba(255, 255, 255, 0.22));
        border: 1px solid var(--glass-border, rgba(255, 255, 255, 0.3));
        border-radius: var(--bs-input-radius, 4px);
        padding: 6px 12px;
        margin-right: 12px;
        cursor: pointer;
        transition: background 0.3s ease, border-color 0.3s ease;
    }

        input[type="file"]::file-selector-button:hover {
            background: rgba(255, 255, 255, 0.35);
            border-color: var(--glass-border-hover, rgba(255, 255, 255, 0.45));
        }

/* ================================================================
   End Global Glassmorphism Styles
================================================================ */

/* ================================================================
   Bootstrap Form-Control and Form-Select Glassmorphism Override
   Ensures Bootstrap forms inherit the glassmorphism effect
================================================================ */

.form-control,
.form-select {
    height: var(--bs-input-height, 48px);
    padding: var(--bs-input-padding, 12px 14px);
    border: 1px solid var(--glass-border, rgba(255, 255, 255, 0.3)) !important;
    border-radius: var(--bs-input-radius, 4px);
    background: var(--glass-bg, rgba(255, 255, 255, 0.15)) !important;
    box-shadow: var(--glass-shadow, 0 4px 10px rgba(0, 0, 0, 0.05));
    color: var(--kairo-text-color, var(--bs-input-text, #2C3E50));
    font-family: var(--kairo-font-family, "Segoe UI", Tahoma, Arial, sans-serif);
    font-size: var(--bs-input-font-size, 10px);
    font-weight: var(--bs-input-font-weight, 800);
    transition: background 0.3s ease, border-color 0.3s ease, box-shadow 0.3s ease, outline 0.2s ease;
    outline: 2px solid transparent;
    outline-offset: 2px;
}

    .form-control:hover,
    .form-select:hover {
        background: var(--glass-bg-hover, rgba(255, 255, 255, 0.22)) !important;
        border-color: var(--glass-border-hover, rgba(255, 255, 255, 0.45)) !important;
        box-shadow: var(--glass-shadow-hover, 0 6px 14px rgba(0, 0, 0, 0.08));
    }

    .form-control:focus,
    .form-select:focus {
        background: var(--glass-bg-hover, rgba(255, 255, 255, 0.22)) !important;
        border-color: var(--color-primary, #3b82f6) !important;
        box-shadow: var(--glass-shadow-hover, 0 6px 14px rgba(0, 0, 0, 0.08)) !important;
        outline: 2px solid var(--color-primary, #3b82f6);
        outline-offset: 2px;
    }

    .form-control:focus-visible,
    .form-select:focus-visible {
        outline: 2px solid var(--color-primary, #3b82f6);
        outline-offset: 2px;
    }

textarea.form-control {
    height: auto !important;
    min-height: 32px !important;
    padding: 4px 8px !important;
    line-height: 1.3 !important;
}

.form-select {
    cursor: pointer;
}

    .form-control:disabled,
    .form-select:disabled,
    .form-control[readonly],
    .form-select[readonly] {
        opacity: 0.6;
        cursor: not-allowed;
    }

/* ================================================================
   End Bootstrap Glassmorphism Override
================================================================ */

.bs-btn {
    padding: 8px 10px;
    border: 1px solid var(--kairo-primary-color, var(--bs-focus-color));
    background: var(--kairo-card-bg, var(--white, #fff));
