    border-radius: var(--radius, 3px);
    cursor: pointer;
    font-size: 11px;
    font-family: inherit;
    transition: all 0.2s ease;
}

    .bs-btn:hover:not(:disabled) {
        background: var(--kairo-primary-color, var(--bs-focus-color));
        color: var(--white, #fff);
    }

    .bs-btn:disabled {
        opacity: 0.5;
        cursor: not-allowed;
    }

.bs-btn--primary {
    border-color: var(--kairo-primary-color, var(--bs-focus-color));
    color: var(--white, #fff);
