    box-shadow: 0 2px 6px rgba(0, 0, 0, 0.06), 0 1px 3px rgba(0, 0, 0, 0.04);
    transform: translateX(2px);
}

    .sidebar-item--enhanced:hover .sidebar-item__title {
        color: #4a7c95;
    }

    .sidebar-item--enhanced:hover .sidebar-item__icon {
        color: #3d6a7f;
    }

.sidebar-item--enhanced.active {
    background: linear-gradient(180deg, #eff6ff 0%, #e0f2fe 100%);
    border-left: 3px solid #4a7c95;
    border-color: #cbd5e1;
    border-left-color: #4a7c95;
    color: var(--color-text, var(--color-text-primary, #1e293b));
    box-shadow: 0 2px 6px rgba(74, 124, 149, 0.12), 0 1px 3px rgba(74, 124, 149, 0.08);
}

    .sidebar-item--enhanced.active .sidebar-item__title {
        color: #4a7c95;
        font-weight: 700;
    }

    .sidebar-item--enhanced.active .sidebar-item__description {
        color: #64748b;
    }

    .sidebar-item--enhanced.active .sidebar-item__icon {
        color: #4a7c95;
    }

.sidebar-item i {
    font-size: 12px;
    color: var(--text-light);
}

.nav-label i {
    font-size: 12px;
    color: rgba(255, 255, 255, 0.80);
}

.sidebar-item.sidebar-item--static:hover {
    color: var(--text-dark);
    background: transparent;
}

/* Form Content */
.form-content {
    flex: 1;
    /*padding: 16px 20px; */
    background: rgba(255, 255, 255, 0.08);
    overflow-y: auto;
    height: calc(100vh - var(--title-bar-height));
    scroll-behavior: smooth;
}

    /* Form Section Cards */
    .form-content > .section-header:first-of-type {
        margin-top: 0;
    }

    /* Add subtle card effect to form sections */
    .form-content > .form-row:first-of-type {
        margin-top: 0;
    }

/* 4-Column Grid Layout (Account Maintenance Style) */
.kairo-grid-4 {
    display: grid;
    grid-template-columns: repeat(4, 1fr);
    gap: 16px;
    margin-bottom: 20px;
}

.kairo-field {
    display: flex;
    flex-direction: column;
    gap: 6px;
    min-width: 0;
    /* Prevent overflow */
}

    .kairo-field label {
        font-size: 11px;
        font-weight: 600;
        color: var(--color-text, var(--color-text-primary, #1e293b));
        margin-bottom: 0;
    }

    /* Ensure all inputs within grid fields are same size */
    .kairo-field input[type="text"],
    .kairo-field input[type="date"],
    .kairo-field input[type="number"],
    .kairo-field select,
    .kairo-field textarea {
        width: 100% !important;
        max-width: none !important;
        box-sizing: border-box;
    }

    /* Ensure product control fits grid */
    .kairo-field .kairo-product-control {
        width: 100%;
        max-width: none;
    }

    /* Ensure flex containers with buttons don't overflow */
    .kairo-field > div[style*="display: flex"] {
        width: 100%;
        max-width: none;
    }

/* Responsive - 2 columns on medium screens */
@media (max-width: 1200px) {
    .kairo-grid-4 {
        grid-template-columns: repeat(2, 1fr);
    }
}

/* Responsive - 1 column on small screens */
@media (max-width: 768px) {
    .kairo-grid-4 {
        grid-template-columns: 1fr;
    }
}

/* Child form overlay */
.child-overlay {
    position: absolute;
    top: 0;
    right: 0;
    bottom: 0;
    left: var(--sidebar-width);
    display: none;
    padding: 12px;
    background: rgba(44, 62, 80, 0.18);
    z-index: 999;
    transition: left 0.3s ease;
}

.main-container.sidebar-collapsed .child-overlay {
    left: var(--sidebar-collapsed-width);
}

.child-overlay.is-open {
    display: flex;
}

.child-frame {
    flex: 1;
    min-width: 0;
    min-height: 0;
    border: 1px solid rgba(255, 255, 255, 0.3);
    border-radius: var(--radius);
    background: rgba(245, 246, 248, 0.85);
    backdrop-filter: blur(10px);
    -webkit-backdrop-filter: blur(10px);
    box-shadow: 0 8px 24px rgba(0, 0, 0, 0.1);
    overflow: hidden;
    width: 100%;
    height: 100%;
}

.child-iframe {
    width: 100%;
    height: 100%;
    border: none;
    display: block;
    background: transparent;
}

/* Form Row and Labels */
.form-row {
    display: flex;
    align-items: flex-start;
    gap: 12px;
    margin-bottom: 12px;
    transition: all 0.2s ease;
}

    .form-row:hover {
        background: rgba(74, 144, 226, 0.02);
        border-radius: 4px;
    }

/* Form row hover micro-interaction (padding/margin) – only when theme setting is enabled */
body.form-row-hover-on .form-row:hover {
    padding: 2px 4px;
    margin-left: -4px;
    margin-right: -4px;
}

/* Labels in columns should be above controls */
.col label {
    display: block;
    margin-bottom: 4px;
    font-size: 12px;
    color: var(--text-gray);
    font-weight: 500;
    transition: color 0.2s ease;
}

.form-row:hover .col label {
    color: #333;
}

.label-blue,
[class*="label--blue"],
span.label-blue,
span[class*="label--blue"] {
    color: var(--color-label-mandatory, #2563eb) !important;
    font-family: var(--label-font-family) !important;
    font-size: var(--label-font-size) !important;
    font-weight: var(--label-font-weight) !important;
}

    /* Span elements inside .label-blue labels */
    .label-blue span:not(.required):not([class*="required"]):not(.bts-info-btn):not([class*="info"]),
    [class*="label--blue"] span:not(.required):not([class*="required"]):not(.bts-info-btn):not([class*="info"]) {
        color: var(--color-label-mandatory, #2563eb) !important;
        font-family: var(--label-font-family) !important;
        font-size: var(--label-font-size) !important;
        font-weight: var(--label-font-weight) !important;
    }

    /* Remove asterisks from blue labels */
    .label-blue::after,
    [class*="label--blue"]::after {
        display: none !important;
        content: '' !important;
    }

/* Bootstrap row/col patterns - compact layout */
.row.g-2 {
    --bs-gutter-x: 0.75rem;
    --bs-gutter-y: 0.5rem;
}

.row.mb-2 {
    margin-bottom: 0.5rem !important;
}

/* Ensure labels in Bootstrap columns are above controls */
.row .col-6 label,
.row .col-12 label {
    display: block;
    margin-bottom: 4px;
    font-size: 12px;
    font-weight: 500;
}

/* Compact form controls */
.bs-input-text.form-control {
    padding: 4px 8px;
    font-size: 13px;
    height: 32px;
}

.bs-select.form-control {
    padding: 4px 8px;
    font-size: 13px;
    height: 32px;
}

/* Date Picker Wrapper - Compact */
.de-date-wrapper {
    display: flex;
    align-items: center;
    gap: 0;
    width: 100%;
}

    .de-date-wrapper .bs-input-date {
        flex: 1;
        border-top-right-radius: 0;
        border-bottom-right-radius: 0;
        height: 32px;
    }

/* Ensure input-group items stay on same row */
.input-group {
    display: flex !important;
    align-items: center !important;
    width: 100%;
}

    .input-group .form-control {
        flex: 1;
        min-width: 0;
    }

    .input-group .btn {
        flex-shrink: 0;
        height: 32px !important;
        padding: 0 8px !important;
        display: flex;
        align-items: center;
        justify-content: center;
        padding: 4px 8px;
        font-size: 12px;
    }

.de-date-btn {
    display: flex;
    align-items: center;
    justify-content: center;
    width: 32px;
    height: 32px;
    background: #f0f4f8;
    border: 1px solid var(--color-border, #e2e8f0);
    border-left: none;
    border-radius: 0 4px 4px 0;
    color: var(--primary);
    cursor: pointer;
    transition: all 0.15s ease;
    flex-shrink: 0;
    padding: 0;
    font-size: 14px;
}

    .de-date-btn:hover {
        background: var(--bs-input-bg, #ffffff);
        color: var(--primary-dark);
    }

    .de-date-btn:active {
        background: var(--primary);
        color: white;
    }

/* Passbook Serial ID sizing */
#PassbookSerialID {
    width: 170px;
    max-width: 170px;
}

    #PassbookSerialID + .btn-lookup {
        width: 22px;
        height: 22px;
        padding: 0;
        font-size: 11px;
    }

.checkbox {
    width: 14px;
    height: 14px;
}

/* Two Column Layout */
.form-row.two-col {
    display: flex;
    gap: 16px;
    margin-top: 12px;
    margin-bottom: 12px;
}

    .form-row.two-col .col {
        flex: 1;
        min-width: 0;
    }

        .form-row.two-col .col > label {
            display: block;
            margin-bottom: 4px;
            font-size: 11px;
            font-weight: 600;
        }

        .form-row.two-col .col label {
            font-size: 11px;
            font-weight: 600;
            text-align: left;
        }

        .form-row.two-col .col input,
        .form-row.two-col .col select {
            flex: 1;
            min-width: 0;
            max-width: 100%;
        }

/* Three Column Layout */
.form-row.three-col {
    display: grid;
    grid-template-columns: repeat(3, 1fr);
    gap: 16px;
    margin-top: 12px;
    margin-bottom: 12px;
}

    .form-row.three-col .col {
        display: flex;
        flex-direction: column;
        gap: 4px;
        min-width: 0;
    }

        .form-row.three-col .col label {
            font-size: 0.85rem;
            color: #1a5276;
            font-weight: 600;
        }

        .form-row.three-col .col input,
        .form-row.three-col .col select {
            width: 100%;
        }

/* Four Column Layout - Grid Based for Proper Responsiveness */
.form-row.four-col,
.form-card .form-row.four-col,
.form-section--bts .form-row.four-col,
.form-section--bts .section-content .form-row.four-col {
    display: grid !important;
    grid-template-columns: repeat(4, 1fr) !important;
    gap: 16px !important;
    column-gap: 16px !important;
    row-gap: 12px !important;
    margin-top: 12px;
    margin-bottom: 12px;
}

    .form-row.four-col .col,
    .form-card .form-row.four-col .col,
    .form-section--bts .form-row.four-col .col,
    .form-section--bts .section-content .form-row.four-col .col {
        display: flex !important;
        flex-direction: column !important;
        gap: 6px !important;
        min-width: 0 !important;
        width: 100% !important;
        align-items: flex-start !important;
    }

        .form-row.four-col .col label {
            font-size: 11px;
            color: #1a5276;
            font-weight: 600;
        }

        .form-row.four-col .col input,
        .form-row.four-col .col select,
        .form-row.four-col .col textarea {
            width: 100%;
        }

        /* Column Spanning - Full width fields */
        .form-row.four-col .col[style*="span 4"],
        .form-row.four-col .col.span-4 {
            grid-column: span 4;
        }

        .form-row.four-col .col[style*="span 3"],
        .form-row.four-col .col.span-3 {
            grid-column: span 3;
        }

        .form-row.four-col .col[style*="span 2"],
        .form-row.four-col .col.span-2 {
            grid-column: span 2;
        }

/* Responsive adjustments for multi-column layouts */
@media (max-width: 1200px) {
    .form-row.four-col {
        grid-template-columns: repeat(2, 1fr);
    }

        .form-row.four-col .col[style*="span 4"],
        .form-row.four-col .col.span-4,
        .form-row.four-col .col[style*="span 3"],
        .form-row.four-col .col.span-3 {
            grid-column: span 2;
        }
}

@media (max-width: 768px) {

    .form-row.four-col,
    .form-row.three-col {
        grid-template-columns: 1fr;
    }

        .form-row.four-col .col[style*="span 4"],
        .form-row.four-col .col.span-4,
        .form-row.four-col .col[style*="span 3"],
        .form-row.four-col .col.span-3,
        .form-row.four-col .col[style*="span 2"],
        .form-row.four-col .col.span-2 {
            grid-column: span 1;
        }
}

/* Explicit row splits (used by standardized maintenance screens) */

/*
  IMPORTANT:
  These split helpers are used where we need precise column proportions.
  Using flex-basis percentages + gaps can force wrapping (because gaps add
  extra width). CSS Grid gives stable 25/25/50 and 50/50 layouts.
*/
.form-row.two-col.split-25-25-50,
.form-row.two-col.split-50-50 {
    display: grid;
    align-items: start;
    margin-top: 12px;
    margin-bottom: 12px;
}

.form-row.two-col.split-25-25-50 {
    grid-template-columns: 1fr 1fr 2fr;
    column-gap: 16px;
}

.form-row.two-col.split-50-50 {
    grid-template-columns: 1fr 1fr;
    column-gap: 16px;
}

    /* Stack label above control inside each column (matches maintenance screens) */
    .form-row.two-col.split-25-25-50 > .col,
    .form-row.two-col.split-50-50 > .col {
        display: flex;
        flex-direction: column;
        align-items: stretch;
        gap: 6px;
        min-width: 0;
    }

        .form-row.two-col.split-25-25-50 > .col label,
        .form-row.two-col.split-50-50 > .col label {
            min-width: 0;
            text-align: left;
            padding-right: 0;
        }

@media (max-width: 768px) {

    .form-row.two-col.split-25-25-50,
    .form-row.two-col.split-50-50 {
        grid-template-columns: 1fr;
        row-gap: 12px;
    }
}

/* Three Column Layout */
.form-row.three-col {
    display: flex;
    gap: 8px;
}

    .form-row.three-col .col {
        display: flex;
        align-items: center;
        flex: 1;
        gap: 4px;
    }

        .form-row.three-col .col label {
            min-width: 80px;
        }

        .form-row.three-col .col input,
        .form-row.three-col .col select {
            flex: 0 0 120px;
            max-width: 120px;
        }

/* Lookup Group - inline input with button */
.lookup-group {
    display: flex;
    align-items: center;
    gap: 4px;
    width: 100%;
}

    .lookup-group input {
        flex: 1;
        min-width: 0;
    }

    .lookup-group .input-code {
        flex: 0 0 80px;
        max-width: 80px;
    }

.btn-lookup {
    width: 28px;
    height: 28px;
    padding: 0;
    border: 1px solid var(--border, #dde6ed);
    background: var(--primary, #4a90e2);
    color: #fff;
    border-radius: 4px;
    cursor: pointer;
    display: flex;
    align-items: center;
    justify-content: center;
    flex-shrink: 0;
    transition: all 0.2s ease;
}

    .btn-lookup:hover {
        background: var(--primary-dark, #3a7bc8);
    }

    .btn-lookup i {
        font-size: 12px;
    }

/* Row Divider - faint grey line */
.row-divider {
    height: 1px;
    background: #e5e7eb;
    margin: 16px 0;
    border: none;
}

/* ===== DATA GRID TABLE STYLES ===== */
.table-container {
    width: 100%;
    overflow-x: auto;
    border: 1px solid #d1d5db;
    border-radius: 4px;
    background: #fff;
}

.data-table {
    width: 100%;
    border-collapse: collapse;
    font-size: 12px;
}

    .data-table thead {
        background: linear-gradient(180deg, #4a7c9b 0%, #3d6a85 100%);
        color: #fff;
        position: sticky;
        top: 0;
        z-index: 1;
    }

        .data-table thead th {
            padding: 8px 12px;
            font-weight: 600;
            text-align: left;
            white-space: nowrap;
            border-right: 1px solid rgba(255, 255, 255, 0.2);
        }

            .data-table thead th:last-child {
                border-right: none;
            }

    .data-table tbody tr {
        border-bottom: 1px solid #e5e7eb;
        transition: background 0.15s ease;
    }

        .data-table tbody tr:hover {
            background: #f0f7ff;
        }

        .data-table tbody tr.selected {
            background: #dbeafe;
        }

    .data-table tbody td {
        padding: 8px 12px;
        vertical-align: middle;
        white-space: nowrap;
    }

    .data-table .text-right {
        text-align: right;
    }

    .data-table .text-center {
        text-align: center;
    }

/* Table Action Buttons */
.table-actions {
    display: flex;
    justify-content: center;
    gap: 12px;
    padding: 12px 0;
    margin-top: 8px;
}

    .table-actions .btn-secondary {
        min-width: 100px;
        padding: 8px 20px;
        font-size: 12px;
        font-weight: 600;
        border: 1px solid #d1d5db;
        border-radius: 4px;
        background: #f8fafc;
        color: #374151;
        cursor: pointer;
        transition: all 0.2s ease;
        display: flex;
        align-items: center;
        justify-content: center;
        gap: 6px;
    }

        .table-actions .btn-secondary:hover:not(:disabled) {
            background: #e5e7eb;
            border-color: #9ca3af;
        }

        .table-actions .btn-secondary:disabled {
            opacity: 0.5;
            cursor: not-allowed;
        }

        .table-actions .btn-secondary.btn-primary-action {
            background: linear-gradient(180deg, #4a7c9b 0%, #3d6a85 100%);
            color: #fff;
            border-color: #3d6a85;
        }

            .table-actions .btn-secondary.btn-primary-action:hover:not(:disabled) {
                background: linear-gradient(180deg, #3d6a85 0%, #325a72 100%);
            }

/* Money/Balance fields - right align */
input[id*="Balance"],
input[id*="balance"],
input[id*="Amount"],
input[id*="amount"],
input[id*="Credits"],
input[id*="Debits"],
input[id*="Interest"],
input[id*="Power"],
input[id*="Rate"],
input[id*="Charges"],
.money-field,
input[data-format="money"],
input[data-format="currency"] {
    text-align: right !important;
    font-variant-numeric: tabular-nums;
}

/* Remove glassmorphism styling from balance inputs */
input[id*="Balance"],
input[id*="balance"] {
    background: transparent !important;
    backdrop-filter: none !important;
    -webkit-backdrop-filter: none !important;
    box-shadow: none !important;
    border: 1px solid #ddd !important;
}

/* Buttons */
.btn-lookup {
    width: 28px;
    height: 28px;
    padding: 0;
    border: 1px solid var(--primary);
    background: var(--white);
    color: var(--primary);
    border-radius: var(--radius);
    cursor: pointer;
    font-size: 10px;
    display: flex;
    align-items: center;
    justify-content: center;
    transition: all 0.2s ease;
    box-shadow: 0 1px 2px rgba(0, 0, 0, 0.05);
}

    .btn-lookup:hover {
        background: var(--primary);
        color: var(--white);
        transform: scale(1.05);
        box-shadow: 0 2px 4px rgba(74, 144, 226, 0.3);
    }

    .btn-lookup:active {
        transform: scale(0.95);
    }

.btn-plus {
    width: var(--bs-input-height);
    height: var(--bs-input-height);
    padding: 0;
    border: 1px solid var(--border);
    background: var(--white);
    cursor: pointer;
    font-size: 12px;
    color: var(--text-gray);
    border-radius: var(--radius);
    transition: all 0.2s ease;
    align-self: center;
    display: flex;
    align-items: center;
    justify-content: center;
    box-shadow: 0 1px 2px rgba(0, 0, 0, 0.05);
}

    .btn-plus:hover {
        border-color: var(--primary);
        color: var(--primary);
        background: rgba(74, 144, 226, 0.08);
        transform: scale(1.05);
        box-shadow: 0 2px 4px rgba(74, 144, 226, 0.2);
    }

    .btn-plus:active {
        transform: scale(0.95);
    }

/* Behind The Scene - Card Layout */
.behind-scene {
    margin: 16px 0;
}


.bts-card-grid {
    display: grid;
    grid-template-columns: repeat(auto-fit, minmax(260px, 1fr));
    gap: 16px;
}

.bts-card {
    background: #f9fafb;
    border: 1px solid #e5e7eb;
    border-radius: 12px;
    padding: 16px;
    box-shadow: 0 1px 2px rgba(15, 23, 42, 0.04);
}

.bts-card__header {
    display: flex;
    align-items: center;
    gap: 10px;
    margin-bottom: 12px;
}

.bts-card__icon {
    width: 32px;
    height: 32px;
    border-radius: 10px;
    background: #eef2ff;
    color: var(--copilot-primary, #2563eb);
    display: flex;
    align-items: center;
    justify-content: center;
    font-size: 0.95rem;
    flex-shrink: 0;
}

.bts-card__title {
    font-size: 0.95rem;
    font-weight: 700;
    letter-spacing: 0.3px;
    color: var(--color-text, var(--color-text-primary, #0f172a));
}

.bts-card__body {
    display: grid;
    grid-template-columns: repeat(auto-fit, minmax(220px, 1fr));
    gap: 12px;
}

.bts-field {
    background: #ffffff;
    border: 1px solid #e5e7eb;
    border-radius: 8px;
    padding: 8px 10px;
    display: flex;
    flex-direction: column;
    gap: 4px;
}

.bts-field__label {
    font-size: 0.7rem;
    font-weight: 700;
    color: #6b7280;
    text-transform: uppercase;
    letter-spacing: 0.5px;
}

.bts-field__label-row {
    display: flex;
    align-items: center;
    justify-content: space-between;
    gap: 8px;
}

.bts-field__value {
    font-size: 0.95rem;
    font-weight: 650;
    color: #111827;
    word-break: break-word;
}

.bts-field--numeric .bts-field__value {
    text-align: right;
    font-variant-numeric: tabular-nums;
    font-feature-settings: 'tnum' 1, 'lnum' 1;
