/* Action Panel */
.action-panel {
    width: var(--action-panel-width);
    flex: 0 0 var(--action-panel-width);
    background: rgba(255, 255, 255, 0.12);
    backdrop-filter: blur(8px);
    -webkit-backdrop-filter: blur(8px);
    border-left: 1px solid rgba(255, 255, 255, 0.25);
    box-shadow: -2px 0 10px rgba(0, 0, 0, 0.03);
    padding: 8px 6px;
    display: flex;
    flex-direction: column;
    gap: 10px;
    height: calc(100vh - var(--title-bar-height));
    overflow-y: auto;
}

.nav-group {
    display: flex;
    align-items: center;
    justify-content: center;
    gap: 4px;
    font-size: 10px;
    color: var(--text-gray);
}

.btn-nav {
    width: 28px;
    height: 28px;
    border-radius: 999px;
    border: 1px solid var(--primary);
    background: var(--white);
    color: var(--primary);
    cursor: pointer;
    font-size: 10px;
    display: flex;
    align-items: center;
    justify-content: center;
    transition: var(--transition);
}

    .btn-nav.green {
        border-color: var(--success);
        color: var(--success);
    }

        .btn-nav.green:hover {
            background: var(--success);
            color: var(--white);
        }

.action-buttons {
    display: flex;
    flex-direction: column;
    gap: 4px;
    margin-top: auto;
}

.btn-action {
    padding: 8px 10px;
    border: 1px solid var(--primary);
    background: var(--white);
    color: var(--primary);
    border-radius: var(--radius);
    cursor: pointer;
    font-size: 11px;
    font-family: inherit;
    transition: var(--transition);
}

    .btn-action:hover:not(:disabled) {
        background: var(--primary);
        color: var(--white);
    }

    .btn-action:disabled {
        opacity: 0.5;
        cursor: not-allowed;
    }

    .btn-action.underline {
        text-decoration: underline;
        box-shadow: 0 0 0 3px rgba(74, 144, 226, 0.16);
    }

/* Action button color mapping - all use theme primary for unified default */
.action-buttons .btn-action:nth-child(1),
.action-buttons .btn-action:nth-child(2),
.action-buttons .btn-action:nth-child(3),
.action-buttons .btn-action:nth-child(4),
.action-buttons .btn-action:nth-child(5),
.action-buttons .btn-action:nth-child(6),
.action-buttons .btn-action:nth-child(7) {
    border-color: var(--primary);
