}

    .action-buttons .btn-action:nth-child(1):hover:not(:disabled),
    .action-buttons .btn-action:nth-child(2):hover:not(:disabled),
    .action-buttons .btn-action:nth-child(3):hover:not(:disabled),
    .action-buttons .btn-action:nth-child(4):hover:not(:disabled),
    .action-buttons .btn-action:nth-child(5):hover:not(:disabled),
