.cm-stepper__nav {
    display: flex;
    flex-direction: row;
    flex-wrap: nowrap;
    align-items: flex-end;
    gap: 0;
    padding: 0 0.35rem;
    border-bottom: 2px solid rgba(15, 23, 42, 0.08);
    background: transparent;
    overflow-x: hidden;
    white-space: nowrap;
    scrollbar-width: thin;
    scrollbar-color: rgba(15, 23, 42, 0.3) transparent;
    position: relative;
}

.cm-stepper__trigger {
    flex: 1 1 0;
    min-width: 70px;
    border-radius: 0.4rem 0.4rem 0 0;
    border: 1px solid transparent;
    border-bottom: none;
    background: rgba(255, 255, 255, 0.7);
    color: #15223f;
    padding: 0.4rem 0.5rem;
    display: flex;
    flex-direction: column;
    align-items: center;
    gap: 0.35rem;
    box-shadow: none;
    transition: background 0.18s ease, border-color 0.18s ease, color 0.18s ease, transform 0.18s ease;
    cursor: pointer;
    position: relative;
}

    .cm-stepper__trigger:not(:last-child)::after {
        content: '';
        position: absolute;
        top: 0.5rem;
        left: calc(50% + 7px);
        right: calc(-100% + 50% - 7px);
        height: 2px;
        background: #d1d5db;
        z-index: -1;
        transition: background 0.3s ease;
    }

    .cm-stepper__trigger.is-completed:not(:last-child)::after {
        background: #22c55e;
    }

    .cm-stepper__trigger:hover {
        background: rgba(255, 255, 255, 0.95);
        transform: translateY(-1px);
    }

    .cm-stepper__trigger.is-active {
        background: #fff;
        border-color: rgba(59, 130, 246, 0.35);
        color: #0f1d40;
        box-shadow: 0 6px 14px rgba(15, 23, 42, 0.08);
    }

    .cm-stepper__trigger.is-completed {
        border-color: rgba(34, 197, 94, 0.25);
    }

.cm-stepper__number {
    position: relative;
    width: 14px;
    height: 14px;
    border-radius: 50%;
    background: #fff;
    border: 2px solid #d1d5db;
    color: #6b7280;
    display: flex;
    align-items: center;
    justify-content: center;
    font-weight: 600;
    font-size: 0.5rem;
    flex-shrink: 0;
    transition: all 0.3s ease;
    z-index: 1;
}

.cm-stepper__trigger.is-active .cm-stepper__number {
    background: #3b82f6;
    border-color: #3b82f6;
    color: white;
    box-shadow: 0 2px 8px rgba(59, 130, 246, 0.3);
}

.cm-stepper__trigger.is-completed .cm-stepper__number {
    background: #22c55e;
    border-color: #22c55e;
    color: white;
    box-shadow: 0 2px 8px rgba(34, 197, 94, 0.3);
}

.cm-stepper__number-text {
    display: none;
}

.cm-stepper__check-icon {
    display: none;
    position: absolute;
    font-size: 0.5rem;
    font-weight: bold;
}

.cm-stepper__trigger.is-completed .cm-stepper__check-icon {
    display: inline;
}

.cm-stepper__nav::-webkit-scrollbar {
    height: 6px;
}

.cm-stepper__nav::-webkit-scrollbar-thumb {
    background: rgba(15, 23, 42, 0.25);
    border-radius: 999px;
}

.cm-stepper__trigger:focus-visible {
    outline: none;
    box-shadow: 0 0 0 2px rgba(59, 130, 246, 0.25);
}

.cm-stepper__index {
    width: 0.95rem;
    height: 0.95rem;
    border-radius: 999px;
    border: 1px solid rgba(79, 70, 229, 0.35);
    display: inline-flex;
    align-items: center;
    justify-content: center;
    font-weight: 600;
    color: #4f46e5;
    background: #fff;
    font-size: 0.55rem;
}

.cm-stepper__trigger.is-active .cm-stepper__index {
    color: #fff;
    border-color: #4f46e5;
    background: #4f46e5;
}

.cm-stepper__text {
    display: flex;
    flex-direction: column;
    align-items: flex-start;
}

.cm-stepper__label {
    font-size: 0.58rem;
    font-weight: 700;
    color: #111633;
    line-height: 1.1;
    text-align: center;
    word-break: break-word;
    max-width: 100%;
}

.cm-stepper__pill {
    font-size: 0.47rem;
    text-transform: uppercase;
    letter-spacing: 0.08em;
    color: #6b7280;
