/* ------------------------------------------------------------
   Brown Theme for Bill Account Application
   Features a cool light brown palette and KICC watermark.
------------------------------------------------------------ */
body.brown-theme {
    background-color: #efebe9;
    background-image: radial-gradient(at 0% 0%, rgba(141, 110, 99, 0.05) 0px, transparent 50%), radial-gradient(at 100% 100%, rgba(141, 110, 99, 0.05) 0px, transparent 50%), linear-gradient(180deg, #f5f5f5 0%, #efebe9 100%);
    min-height: 100vh;
    position: relative;
}

    body.brown-theme::before {
        content: "";
        position: fixed;
        top: 50%;
        left: 50%;
        transform: translate(-50%, -50%);
        width: min(600px, 80%);
        height: min(600px, 80%);
        background-image: url('../images/kicc-watermark.png');
        background-repeat: no-repeat;
        background-position: center;
        background-size: contain;
        opacity: 0.15;
        /* Increased opacity for better visibility */
        pointer-events: none;
        z-index: -1;
        /* Ensure it stays behind everything */
    }

    body.brown-theme .cm-workspace {
        position: relative;
        z-index: 1;
    }

    body.brown-theme .cm-blue-header {
        background: linear-gradient(180deg, #8d6e63 0%, #6d4c41 100%) !important;
        border-color: #5d4037 !important;
        box-shadow: 0 4px 12px rgba(93, 64, 55, 0.15) !important;
    }

        body.brown-theme .cm-blue-header h5,
        body.brown-theme .cm-blue-header small {
            color: #ffffff !important;
            text-shadow: 0 1px 2px rgba(0, 0, 0, 0.2);
        }

    body.brown-theme .cbs-label,
    body.brown-theme .form-label,
    body.brown-theme .cm-legacy-actions__title,
    body.brown-theme .cm-dataentry-toggle span {
        color: #000000 !important;
        text-shadow: none;
    }

    body.brown-theme .card-surface {
        background: rgba(255, 255, 255, 0.82) !important;
        backdrop-filter: blur(10px) !important;
        border: 1px solid rgba(141, 110, 99, 0.12) !important;
        box-shadow: 0 8px 32px rgba(93, 64, 55, 0.06) !important;
    }

    body.brown-theme .cm-shell__action--success {
        background: #795548 !important;
        border-color: #5d4037 !important;
        color: #fff !important;
    }

        body.brown-theme .cm-shell__action--success:hover {
            background: #5d4037 !important;
            box-shadow: 0 4px 12px rgba(93, 64, 55, 0.3) !important;
        }

    body.brown-theme .cm-shell__action--ghost {
        color: #6d4c41 !important;
        border-color: rgba(109, 76, 65, 0.3) !important;
        background: rgba(255, 255, 255, 0.5) !important;
    }

        body.brown-theme .cm-shell__action--ghost:hover {
            background: rgba(109, 76, 65, 0.08) !important;
            border-color: #6d4c41 !important;
        }

    body.brown-theme .form-control:focus,
    body.brown-theme .form-select:focus {
        border-color: #8d6e63 !important;
        box-shadow: 0 0 0 0.25rem rgba(141, 110, 99, 0.15) !important;
    }

:root {
    /* Copilot / Nimble Theme Palette */
    --copilot-bg-gradient: linear-gradient(135deg, #f3f4f6 0%, #eef2ff 100%);
    --copilot-primary: #2563eb;
    --copilot-primary-hover: #1d4ed8;
    --copilot-secondary: #0f172a;
    --copilot-card-bg: rgba(255, 255, 255, 0.7);
    --copilot-card-border: 1px solid rgba(255, 255, 255, 0.5);
    --copilot-glass-shadow: 0 4px 6px -1px rgba(0, 0, 0, 0.1), 0 2px 4px -1px rgba(0, 0, 0, 0.06);
    --copilot-text-main: #1e293b;
    --copilot-text-muted: #64748b;
    --dashboard-primary: var(--copilot-primary);
    --dashboard-secondary: #4f46e5;
    --dashboard-card: #ffffff;
}

body {
    font-family: 'Montserrat', sans-serif;
    background: var(--copilot-bg-gradient);
    color: var(--copilot-text-main);
    min-height: 100vh;
}

/* Glassmorphism Utilities */
.glass-effect {
    background: rgba(255, 255, 255, 0.65);
    backdrop-filter: blur(12px);
    -webkit-backdrop-filter: blur(12px);
    border: 1px solid rgba(255, 255, 255, 0.3);
    box-shadow: 0 8px 32px 0 rgba(31, 38, 135, 0.07);
}

.auth-page .authBackground {
    background: url('../images/background/Tsedey_Et.png') no-repeat center center;
    background-size: cover;
    background-attachment: scroll;
    min-height: 100vh;
    height: 100vh;
    display: flex;
    align-items: center;
    justify-content: center;
    flex-direction: column;
    overflow: hidden;
    position: relative;
}

.auth-page .form-box {
    background: rgba(255, 255, 255, 0.85);
    backdrop-filter: blur(20px);
    border-radius: 24px;
    padding: 3rem;
    box-shadow: 0 20px 40px rgba(0, 0, 0, 0.08);
    border: 1px solid rgba(255, 255, 255, 0.6);
    max-width: 480px;
    width: 100%;
}

.auth-page .brand-title {
    color: var(--color-text, var(--color-text-primary, #1e293b));
    font-weight: 700;
    letter-spacing: -0.5px;
    margin-top: 1rem;
}

.auth-page .btn.auth-form-btn {
    background: linear-gradient(135deg, #2563eb, #4f46e5);
