.cm-stepper__nav {
    display: flex;
    flex-direction: row;
    flex-wrap: nowrap;
    align-items: flex-end;
    gap: 0.15rem;
    padding: 0 0.35rem;
    border-bottom: 2px solid rgba(15, 23, 42, 0.08);
    background: transparent;
    overflow-x: auto;
    white-space: nowrap;
    scrollbar-width: thin;
    scrollbar-color: rgba(15, 23, 42, 0.3) transparent;
}

.cm-stepper__trigger {
    flex: 1 1 0;
    min-width: 90px;
    border-radius: 0.4rem 0.4rem 0 0;
    border: 1px solid transparent;
    border-bottom: none;
    background: rgba(255, 255, 255, 0.7);
    color: #15223f;
    padding: 0.2rem 0.75rem 0.25rem;
    display: flex;
    flex-direction: column;
    align-items: flex-start;
    gap: 0.1rem;
    box-shadow: none;
    transition: background 0.18s ease, border-color 0.18s ease, color 0.18s ease, transform 0.18s ease;
}

    .cm-stepper__trigger:hover {
        background: rgba(255, 255, 255, 0.95);
        transform: translateY(-1px);
    }

    .cm-stepper__trigger.is-active {
        background: #fff;
        border-color: rgba(59, 130, 246, 0.35);
        color: #0f1d40;
        box-shadow: 0 6px 14px rgba(15, 23, 42, 0.08);
    }

.cm-stepper__nav::-webkit-scrollbar {
    height: 6px;
}

.cm-stepper__nav::-webkit-scrollbar-thumb {
    background: rgba(15, 23, 42, 0.25);
    border-radius: 999px;
}

.cm-stepper__trigger:focus-visible {
    outline: none;
    box-shadow: 0 0 0 2px rgba(59, 130, 246, 0.25);
}

.cm-stepper__index {
    width: 0.95rem;
    height: 0.95rem;
    border-radius: 999px;
    border: 1px solid rgba(79, 70, 229, 0.35);
    display: inline-flex;
    align-items: center;
    justify-content: center;
    font-weight: 600;
    color: #4f46e5;
    background: #fff;
    font-size: 0.55rem;
}

.cm-stepper__trigger.is-active .cm-stepper__index {
    color: #fff;
    border-color: #4f46e5;
    background: #4f46e5;
}

.cm-stepper__text {
    display: flex;
    flex-direction: column;
    align-items: flex-start;
}

.cm-stepper__label {
    font-size: 0.63rem;
    font-weight: 600;
    color: #111633;
    line-height: 1.1;
}

.cm-stepper__pill {
    font-size: 0.47rem;
    text-transform: uppercase;
    letter-spacing: 0.08em;
    color: #6b7280;
    line-height: 1.2;
}

.cm-stepper__trigger.is-active .cm-stepper__pill {
    color: #2c3370;
}

