/* ============================================================================
   SUBMODULE MODAL STYLING - Covers main form area, leaves sidebar visible
   Used for loan-application, account-maintenance, and other modules with sidebars
   ============================================================================ */

/* Define CSS variable for submodule modal offset */
:root {
    --submodule-modal-left: 250px;
    /* Default: expanded sidebar width */
}

/* Dynamic sidebar width tracking */
.main-container:has(.sidebar:not(.collapsed)) ~ .submodule-modal,
body:has(.sidebar:not(.collapsed)) .submodule-modal {
    --submodule-modal-left: 250px;
}

.main-container:has(.sidebar.collapsed) ~ .submodule-modal,
body:has(.sidebar.collapsed) .submodule-modal {
    --submodule-modal-left: 56px;
}

/* When sidebar is hidden (maximized window or no sidebar) */
.window.maximized .submodule-modal,
body:has(.window.maximized) .submodule-modal,
body:not(:has(.sidebar)) .submodule-modal {
    --submodule-modal-left: 0px;
}

.submodule-modal {
    position: fixed !important;
    top: 0 !important;
    left: var(--submodule-modal-left, 250px) !important;
    right: 0 !important;
    bottom: 0 !important;
    width: calc(100% - var(--submodule-modal-left, 250px)) !important;
    z-index: 1055 !important;
    /* Above action-panel */
    background: transparent;
    display: none;
}

/* Hide action panel when submodule modal is open */
body.modal-open .action-panel {
    z-index: 1050;
    /* Below submodule-modal */
}

.submodule-modal.show {
    display: block !important;
}

/* Modal dialog fills the available space with spacing */
.submodule-modal .modal-dialog {
    position: relative;
    margin: 12px;
    max-width: calc(100% - 24px);
    width: calc(100% - 24px);
    height: calc(100% - 24px);
    display: flex;
    align-items: stretch;
}

.submodule-modal .modal-content {
    width: 100%;
    height: 100%;
    border: 1px solid rgba(0, 0, 0, 0.1);
    border-radius: 8px;
    background: #f4f8f9;
    display: flex;
    flex-direction: column;
    box-shadow: 0 8px 32px rgba(0, 0, 0, 0.2);
    overflow: hidden;
}

/* When parent window is maximized - more spacing and centered */
.window.maximized .submodule-modal .modal-dialog,
body:has(.window.maximized) .submodule-modal .modal-dialog {
    margin: 20px;
    max-width: calc(100% - 40px);
    width: calc(100% - 40px);
    height: calc(100% - 40px);
}

.submodule-modal .modal-content iframe {
    width: 100%;
    height: 100%;
    border: none;
    flex: 1;
}

/* Override Bootstrap modal backdrop for submodule modals */
.submodule-modal ~ .modal-backdrop,
.submodule-modal + .modal-backdrop {
    display: none !important;
}

/* Ensure sidebar remains visible when modal is open */
body.modal-open .sidebar {
    z-index: 1040;
}

/* Kairo search modal backdrop - higher z-index */
.kairo-search-modal ~ .modal-backdrop,
.kairo-search-modal + .modal-backdrop {
    z-index: 1055 !important;
}

/* ============================================================================
   KAIRO SEARCH MODAL STYLES - Matching Merge Client Accounts Design
   Clean Bootstrap-based styling for uniformity across all modules
   ============================================================================ */

/* Modal Container - High z-index to prevent overlap */
.kairo-search-modal {
    z-index: 1060 !important;
}

    .kairo-search-modal .modal-dialog {
        max-width: 600px;
        margin: 1.75rem auto;
    }

        .kairo-search-modal .modal-dialog.modal-lg {
            max-width: 700px;
        }

    .kairo-search-modal .modal-content {
        border: none;
        border-radius: 8px;
        box-shadow: 0 10px 40px rgba(0, 0, 0, 0.25);
        overflow: hidden;
    }

    /* Modal Header - Dark Navy Gradient */
    .kairo-search-modal .modal-header {
        background: linear-gradient(180deg, var(--color-header, var(--color-primary, #4a7c95)) 0%, color-mix(in srgb, var(--color-header, var(--color-primary, #4a7c95)) 85%, black 15%) 100%) !important;
        padding: 12px 16px;
        border: none;
        color: #ffffff !important;
    }

    .kairo-search-modal .modal-title {
        color: white;
        font-size: 14px;
        font-weight: 600;
        display: flex;
        align-items: center;
    }

        .kairo-search-modal .modal-title i {
            margin-right: 8px;
            font-size: 16px;
        }

    .kairo-search-modal .btn-close {
        filter: brightness(0) invert(1);
        opacity: 0.8;
        font-size: 12px;
    }

        .kairo-search-modal .btn-close:hover {
            opacity: 1;
        }

    /* Modal Body - No padding, sections handle their own */
    .kairo-search-modal .modal-body {
        padding: 0;
        background: #ffffff;
    }

    /* Filter/Search Section - Light background */
    .kairo-search-modal .search-filters {
        padding: 16px;
        background: #f8f9fa;
        border-bottom: 1px solid #dee2e6;
    }

    /* Filter Labels - Above inputs */
    .kairo-search-modal .filter-label {
        display: block;
        font-size: 12px;
        font-weight: 600;
        color: #6c757d;
        margin-bottom: 4px;
    }

    /* Filter Inputs */
    .kairo-search-modal .filter-input {
        width: 100%;
        height: 32px;
        padding: 6px 10px;
        font-size: 12px;
        border: 1px solid #ced4da;
        border-radius: 4px;
        background: #ffffff;
        color: #495057;
        transition: border-color 0.15s, box-shadow 0.15s;
    }

        .kairo-search-modal .filter-input:focus {
            outline: none;
            border-color: #1a5276;
            box-shadow: 0 0 0 2px rgba(26, 82, 118, 0.15);
        }

        .kairo-search-modal .filter-input::placeholder {
            color: #adb5bd;
        }

    /* Filter Row Grid */
    .kairo-search-modal .filter-row {
        display: grid;
        grid-template-columns: repeat(2, 1fr);
        gap: 12px;
        margin-bottom: 12px;
    }

        .kairo-search-modal .filter-row:last-of-type {
            margin-bottom: 0;
        }

    .kairo-search-modal .filter-group {
        display: flex;
        flex-direction: column;
    }

    /* Search Actions */
    .kairo-search-modal .search-actions {
        display: flex;
        justify-content: center;
        gap: 8px;
        margin-top: 10px;
        padding-top: 0;
        border-top: none;
    }

    /* Search Button - Primary Blue */
    .kairo-search-modal .btn-search {
        display: inline-flex;
        align-items: center;
        gap: 6px;
        padding: 8px 16px;
        font-size: 12px;
        font-weight: 600;
        border-radius: 4px;
        border: none;
        cursor: pointer;
        transition: all 0.2s;
        background: #2563eb;
        color: white;
    }

        .kairo-search-modal .btn-search:hover {
            background: #1d4ed8;
        }

        .kairo-search-modal .btn-search i {
            font-size: 12px;
        }

    /* Clear Button */
    .kairo-search-modal .btn-clear {
        display: inline-flex;
        align-items: center;
        gap: 6px;
        padding: 8px 16px;
        font-size: 12px;
        font-weight: 500;
        border-radius: 4px;
        border: 1px solid #ced4da;
        cursor: pointer;
        transition: all 0.2s;
        background: #ffffff;
        color: #6c757d;
    }

        .kairo-search-modal .btn-clear:hover {
            background: #f8f9fa;
            color: #495057;
        }

    /* Results Table Container */
    .kairo-search-modal .results-container {
        max-height: 300px;
        overflow-y: auto;
    }

    /* Results Table */
    .kairo-search-modal .results-table {
        width: 100%;
        margin-bottom: 0;
        font-size: 12px;
        border-collapse: collapse;
    }

        .kairo-search-modal .results-table thead th {
            background: linear-gradient(180deg, var(--color-header, var(--color-primary, #1a5276)) 0%, color-mix(in srgb, var(--color-header, var(--color-primary, #1a5276)) 85%, black 15%) 100%);
            color: white;
            font-size: 12px;
            font-weight: 600;
            padding: 10px 12px;
            border: 1px solid rgba(255, 255, 255, 0.2);
            position: sticky;
            top: 0;
            z-index: 1;
            text-align: left;
        }

        .kairo-search-modal .results-table tbody tr {
            cursor: pointer;
            transition: background-color 0.15s;
        }

            .kairo-search-modal .results-table tbody tr:hover {
                background-color: #e3f2fd;
            }

            .kairo-search-modal .results-table tbody tr.selected {
                background-color: #bbdefb !important;
            }

        .kairo-search-modal .results-table tbody td {
            padding: 8px 12px;
            border: 1px solid #dee2e6;
            color: #212529;
            vertical-align: middle;
        }

        .kairo-search-modal .results-table tbody tr:last-child td {
            border-bottom: 1px solid #dee2e6;
        }

    /* Empty State / No Results */
    .kairo-search-modal .empty-message {
        text-align: center;
        padding: 40px 20px;
        color: #6c757d;
    }

        .kairo-search-modal .empty-message i {
            display: block;
            font-size: 32px;
            margin-bottom: 12px;
            opacity: 0.5;
        }

    /* Pagination */
    .kairo-search-modal .pagination-bar {
        display: flex;
        justify-content: space-between;
        align-items: center;
        padding: 10px 16px;
        background: #f8f9fa;
        border-top: 1px solid #dee2e6;
    }

    .kairo-search-modal .pagination-buttons {
        display: flex;
        gap: 8px;
    }

    .kairo-search-modal .pagination-btn {
        display: inline-flex;
        align-items: center;
        gap: 4px;
        padding: 6px 12px;
        font-size: 12px;
        font-weight: 500;
        border: 1px solid #ced4da;
        border-radius: 4px;
        background: #ffffff;
        color: #495057;
        cursor: pointer;
        transition: all 0.15s;
    }

        .kairo-search-modal .pagination-btn:hover:not(:disabled) {
            background: var(--color-primary, var(--color-header, #4a7c95));
            color: white;
            border-color: var(--color-primary, var(--color-header, #4a7c95));
        }

        .kairo-search-modal .pagination-btn:disabled {
            opacity: 0.5;
            cursor: not-allowed;
        }

    .kairo-search-modal .pagination-info {
        font-size: 12px;
        color: #6c757d;
    }

    /* Modal Footer */
    .kairo-search-modal .modal-footer {
        padding: 10px 16px;
        border-top: none;
        background: linear-gradient(180deg, var(--color-header, var(--color-primary, #4a7c95)) 0%, color-mix(in srgb, var(--color-header, var(--color-primary, #4a7c95)) 85%, black 15%) 100%);
        display: flex;
        justify-content: center;
        gap: 8px;
    }

    /* Cancel Button */
    .kairo-search-modal .btn-cancel {
        display: inline-flex;
        align-items: center;
        gap: 6px;
        padding: 8px 16px;
        font-size: 12px;
        font-weight: 500;
        border-radius: 4px;
        border: 1px solid #ced4da;
        cursor: pointer;
        transition: all 0.15s;
        background: #6c757d;
        color: white;
    }

        .kairo-search-modal .btn-cancel:hover {
            background: #5a6268;
        }

    /* Select Button - Teal/Green */
    .kairo-search-modal .btn-select {
        display: inline-flex;
        align-items: center;
        gap: 6px;
        padding: 8px 16px;
        font-size: 12px;
        font-weight: 600;
        border-radius: 4px;
        border: none;
        cursor: pointer;
        transition: all 0.15s;
        background: #17a2b8;
        color: white;
    }

        .kairo-search-modal .btn-select:hover:not(:disabled) {
            background: #138496;
        }

        .kairo-search-modal .btn-select:disabled {
            opacity: 0.6;
            cursor: not-allowed;
        }

    /* ============================================================================
   LEGACY SUPPORT - Mapping old classes to new design
   ============================================================================ */

    /* Map old search-section to new search-filters */
    .kairo-search-modal .search-section {
        padding: 12px 20px;
        background: #fafafa;
        border-bottom: 1px solid #dee2e6;
        border-radius: 0;
        margin-bottom: 0;
    }

    /* Map old search-row to filter-row */
    .kairo-search-modal .search-row {
        display: grid;
        grid-template-columns: repeat(2, 1fr);
        gap: 12px;
        margin-bottom: 12px;
    }

    /* Map old search-field to new vertical layout */
    .kairo-search-modal .search-field {
        display: flex;
        flex-direction: column;
        gap: 4px;
    }

    /* Map old search-label to filter-label */
    .kairo-search-modal .search-label {
        display: block;
        font-size: 12px;
        font-weight: 600;
        color: var(--color-primary, var(--color-header, #4a7c95));
        margin-bottom: 4px;
        text-align: left;
        min-width: unset;
        padding-right: 0;
    }

    /* Map old search-input to filter-input */
    .kairo-search-modal .search-input {
        width: 100%;
        height: 32px;
        padding: 6px 10px;
        font-size: 12px;
        border: 1px solid #ced4da;
        border-radius: 4px;
        background: #ffffff;
        color: #495057;
        flex: unset;
    }

        .kairo-search-modal .search-input:focus {
            outline: none;
            border-color: var(--color-primary, var(--color-header, #4a7c95));
            box-shadow: 0 0 0 2px rgba(74, 124, 149, 0.2);
        }

    /* Map old search-select */
    .kairo-search-modal .search-select,
    .kairo-search-modal .search-operator {
        width: 100%;
        height: 32px;
        padding: 6px 10px;
        font-size: 12px;
        border: 1px solid #ced4da;
        border-radius: 4px;
        background: #ffffff;
        color: #495057;
    }

    /* Search input group - horizontal layout for operator + input */
    .kairo-search-modal .search-input-group {
        display: flex;
        gap: 8px;
        flex: 1;
    }

        .kairo-search-modal .search-input-group .search-select {
            width: 100px;
            flex-shrink: 0;
        }

        .kairo-search-modal .search-input-group .search-input {
            flex: 1;
        }

    /* Map old search-btn classes */
    .kairo-search-modal .search-btn {
        display: inline-flex;
        align-items: center;
        gap: 6px;
        padding: 8px 16px;
        font-size: 12px;
        font-weight: 600;
        border-radius: 4px;
        border: none;
        cursor: pointer;
        transition: all 0.15s;
    }

    .kairo-search-modal .search-btn-primary {
        background: #e8ecf0;
        color: #1e293b;
        border: 1px solid #adb5bd;
    }

        .kairo-search-modal .search-btn-primary:hover {
            background: var(--color-primary, var(--color-header, #4a7c95));
            color: white;
            border-color: var(--color-primary, var(--color-header, #4a7c95));
        }

    .kairo-search-modal .search-btn-secondary {
        background: #ffffff;
        color: #6c757d;
        border: 1px solid #ced4da;
    }

        .kairo-search-modal .search-btn-secondary:hover {
            background: #f8f9fa;
            color: #495057;
        }

    /* Map old modal-btn classes */
    .kairo-search-modal .modal-btn {
        display: inline-flex;
        align-items: center;
        gap: 6px;
        padding: 8px 16px;
        font-size: 12px;
        font-weight: 500;
        border-radius: 4px;
        border: none;
        cursor: pointer;
        transition: all 0.15s;
    }

    .kairo-search-modal .modal-btn-secondary {
        background: #e8ecf0;
        color: #1e293b;
        border: 1px solid rgba(255,255,255,0.4);
    }

        .kairo-search-modal .modal-btn-secondary:hover {
            background: #ffffff;
            color: #1e293b;
        }

    .kairo-search-modal .modal-btn-success,
    .kairo-search-modal .modal-btn-primary {
        background: #e8ecf0;
        color: #1e293b;
        border: 1px solid rgba(255,255,255,0.4);
    }

        .kairo-search-modal .modal-btn-success:hover:not(:disabled),
        .kairo-search-modal .modal-btn-primary:hover:not(:disabled) {
            background: #ffffff;
            color: #1e293b;
        }

        .kairo-search-modal .modal-btn-success:disabled,
        .kairo-search-modal .modal-btn-primary:disabled {
            opacity: 0.5;
            cursor: not-allowed;
        }

    /* Results header */
    .kairo-search-modal .results-header {
        display: none;
        /* Hide the separate results header for cleaner look */
    }

    /* Results table wrapper */
    .kairo-search-modal .results-table-wrapper {
        overflow-y: auto;
        max-height: 300px;
        background: #ffffff;
        border-radius: 4px;
        border: 1px solid #ced4da;
        margin: 12px 16px;
    }

    /* No results message */
    .kairo-search-modal .no-results {
        text-align: center;
        padding: 40px 20px;
        color: #6c757d;
        font-style: normal;
    }

        .kairo-search-modal .no-results i {
            display: block;
            font-size: 32px;
            margin-bottom: 12px;
            opacity: 0.5;
        }

    /* Loading Animation */
    .kairo-search-modal .bi-hourglass-split {
        animation: spin 2s linear infinite;
    }

/* ================================================================
   Theme Configuration - Color Input Styling
   Scoped to .am-card to prevent layout interference
================================================================ */

/* Sidebar Navigation */
.am-card .list-group {
    border: 1px solid #e5e7eb;
    border-radius: 6px;
    overflow: hidden;
}

.am-card .list-group-item {
    border: none;
    border-bottom: 1px solid #f3f4f6;
    padding: 0.75rem 1rem;
    font-size: 0.95rem;
    cursor: pointer;
    transition: all 0.2s ease;
    background-color: #f9fafb;
    color: #4b5563;
    text-align: left;
}

    .am-card .list-group-item:last-child {
        border-bottom: none;
    }

    .am-card .list-group-item:hover {
        background-color: #f3f4f6;
        color: #2c3e50;
    }

    .am-card .list-group-item.active {
        background-color: #dbeafe;
        color: #1e40af;
        border-left: 4px solid #3b82f6;
        font-weight: 600;
    }

    .am-card .list-group-item i {
        margin-right: 0.5rem;
    }

/* Theme Sections */
.am-card .theme-section {
    animation: fadeIn 0.3s ease;
}

    .am-card .theme-section[style*="display: none"] {
        display: none !important;
    }

@keyframes fadeIn {
    from {
        opacity: 0;
        transform: translateY(-5px);
    }

    to {
        opacity: 1;
        transform: translateY(0);
    }
}

/* Color Controls */
.am-card .theme-color-control {
    display: flex;
    align-items: center;
    gap: 0.5rem;
    flex-wrap: wrap;
}

.am-card .theme-color-input {
    width: 60px;
    height: 42px;
    border: 2px solid #dee2e6;
    border-radius: 4px;
    cursor: pointer;
    flex-shrink: 0;
    transition: border-color 0.2s ease, box-shadow 0.2s ease;
    padding: 2px;
}

    .am-card .theme-color-input:hover {
        border-color: #999;
        box-shadow: 0 0 8px rgba(0, 0, 0, 0.12);
    }

    .am-card .theme-color-input:focus {
        outline: 2px solid #0066cc;
        outline-offset: 2px;
        border-color: #0066cc;
    }

    .am-card .theme-color-input:active {
        transform: scale(0.98);
    }

.am-card .color-value-display {
    flex: 0 0 100px;
    font-family: monospace;
    font-size: 0.9rem;
    text-transform: uppercase;
}

/* ============================================
   BEHIND THE SCENE - Card-Based Layout
   ============================================ */

/* Card Grid Container */
.bts-card-grid {
    display: grid;
    grid-template-columns: repeat(auto-fit, minmax(320px, 1fr));
    gap: 1.25rem;
    padding: 1rem 0;
}

@media (min-width: 992px) {
    .bts-card-grid {
        grid-template-columns: repeat(2, 1fr);
    }
}

@media (min-width: 1400px) {
    .bts-card-grid {
        grid-template-columns: repeat(3, 1fr);
    }
}

/* Individual Card */
.bts-card {
    background: #fafbfc;
    border: 1px solid #e4e7eb;
    border-radius: 8px;
    padding: 1.25rem;
    transition: border-color 0.2s ease, box-shadow 0.15s ease;
}

    .bts-card:hover {
        border-color: #d1d5db;
        box-shadow: 0 2px 8px rgba(0, 0, 0, 0.04);
    }

/* Card Title */
.bts-card__title {
    font-size: 0.75rem;
    font-weight: 600;
    color: #64748b;
    text-transform: uppercase;
    letter-spacing: 0.05em;
    margin: 0 0 1rem 0;
    padding-bottom: 0.5rem;
    border-bottom: 1px solid #e4e7eb;
}

/* Card Content */
.bts-card__content {
    display: flex;
    flex-direction: column;
    gap: 0.875rem;
}

/* Field Container */
.bts-field {
    display: flex;
    flex-direction: column;
    gap: 0.25rem;
}

.bts-field--compact {
    gap: 0.15rem;
}

.bts-field--highlight {
    padding: 0.5rem;
    background: #f8f9fa;
    border-radius: 4px;
    border-left: 3px solid #3b82f6;
}

/* Label */
.bts-label {
    font-size: 0.688rem;
    font-weight: 500;
    color: #6b7280;
    text-transform: uppercase;
    letter-spacing: 0.03em;
    line-height: 1.3;
    margin: 0;
    padding: 0;
}

/* Value */
.bts-value {
    font-size: 1rem;
    font-weight: 600;
    color: #1f2937;
    line-height: 1.5;
    word-break: break-word;
    padding: 0;
    margin: 0;
    background: transparent;
    border: none;
    display: block;
}

/* Value Variants */
.bts-value--primary {
    font-size: 1.125rem;
    font-weight: 700;
    color: var(--color-text, var(--color-text-primary, #0f172a));
}

.bts-value--small {
    font-size: 0.875rem;
    font-weight: 500;
    color: #4b5563;
}

.bts-value--money,
.bts-value--percent {
    text-align: right;
    font-family: 'Courier New', Consolas, monospace;
    font-variant-numeric: tabular-nums;
}

.bts-value--date {
    font-family: 'Courier New', Consolas, monospace;
    font-size: 0.9rem;
}

.bts-value--status {
    display: inline-flex;
    align-items: center;
    padding: 0.25rem 0.75rem;
    border-radius: 12px;
    font-size: 0.813rem;
    font-weight: 600;
    background: #e5e7eb;
    color: #374151;
    width: fit-content;
    text-transform: capitalize;
}

    /* Status Color Variants */
    .bts-value--status[data-status="active"],
    .bts-value--status:is([id*="Status"]):not(:empty):not([data-status]) {
        background: #d1fae5;
        color: #065f46;
    }

    .bts-value--status[data-status="inactive"] {
        background: #fee2e2;
        color: #991b1b;
    }

    .bts-value--status[data-status="dormant"] {
        background: #fef3c7;
        color: #92400e;
    }

    .bts-value--status[data-status="closed"] {
        background: #e5e7eb;
        color: #4b5563;
    }

/* Empty State */
.bts-value:empty::before,
.bts-value:is(:not(:empty)):has(br)::before {
    content: '—';
    color: #9ca3af;
    font-style: italic;
}

/* Responsive Adjustments */
@media (max-width: 768px) {
    .bts-card-grid {
        grid-template-columns: 1fr;
        gap: 1rem;
    }

    .bts-card {
        padding: 1rem;
    }

    .bts-value--primary {
        font-size: 1rem;
    }
}

/* ============================================
   REMINDER MODAL POPUP
   ============================================ */

/* ============================================
   REMINDER MODAL - SYSTEM THEME STYLED
   ============================================ */

.reminder-modal {
    position: fixed;
    top: 0;
    left: 0;
    width: 100%;
    height: 100%;
    display: flex;
    align-items: center;
    justify-content: center;
    z-index: 10000;
}

    .reminder-modal[hidden] {
        display: none !important;
    }

.reminder-modal__backdrop {
    position: absolute;
    top: 0;
    left: 0;
    width: 100%;
    height: 100%;
    background: rgba(0, 0, 0, 0.4);
    backdrop-filter: blur(3px);
    animation: fadeIn 0.2s ease-out;
}

@keyframes fadeIn {
    from {
        opacity: 0;
    }

    to {
        opacity: 1;
    }
}

.reminder-modal__content {
    position: relative;
    background: #ffffff;
    border-radius: 6px;
    width: 85%;
    max-width: 420px;
    animation: slideUp 0.2s ease-out;
    overflow: hidden;
    box-shadow: 0 8px 32px rgba(0, 0, 0, 0.12), 0 2px 8px rgba(0, 0, 0, 0.08);
    border: 1px solid #e5e7eb;
}

@keyframes slideUp {
    from {
