/* ============================================================================
   MESSAGE BAR / TOAST NOTIFICATIONS
   ============================================================================ */
.de-message-bar {
    display: none;
    align-items: center;
    gap: 8px;
    padding: 10px 16px;
    font-size: 13px;
    background: #fef3c7;
    border-top: 2px solid #fcd34d;
    color: #92400e;
    flex-shrink: 0;
    transition: all 0.3s ease;
}

    .de-message-bar.show {
        display: flex;
    }

    .de-message-bar.error {
        background: #fee2e2;
        border-color: #ef4444;
        color: #991b1b;
    }

    .de-message-bar.success {
        background: #d1fae5;
        border-color: #10b981;
        color: #065f46;
    }

    .de-message-bar.info {
        background: #dbeafe;
        border-color: #3b82f6;
        color: #1e40af;
    }

    .de-message-bar.warning {
        background: #fef3c7;
        border-color: #fcd34d;
        color: #92400e;
    }

    .de-message-bar i {
        font-size: 16px;
        flex-shrink: 0;
    }

    .de-message-bar span {
        flex: 1;
    }

.de-message-bar__close,
.am-message-panel__close {
    flex-shrink: 0;
    padding: 4px;
    margin: -4px 0 -4px 8px;
    background: none;
    border: none;
    color: inherit;
    opacity: 0.85;
    cursor: pointer;
    border-radius: 4px;
    line-height: 1;
}

    .de-message-bar__close:hover,
    .am-message-panel__close:hover {
        opacity: 1;
    }

    .de-message-bar__close:focus,
    .am-message-panel__close:focus {
        outline: 1px solid currentColor;
        outline-offset: 2px;
    }

