/* ============================================================================
   VALIDATION SUMMARY (Account Maintenance Standard)
   Inline alert banner for form validation and messages
   ============================================================================ */
.validation-summary {
    background: color-mix(in srgb, #ffffff 92%, #ef4444 8%);
    border: 1px solid color-mix(in srgb, #ef4444 30%, #ffffff 70%);
    border-radius: 6px;
    padding: 10px 14px;
    margin-bottom: 14px;
    display: none;
    align-items: center;
    gap: 10px;
    animation: fadeInSummary 0.25s ease;
}

    .validation-summary.is-visible {
        display: flex;
    }

.validation-summary__icon {
    color: color-mix(in srgb, #ef4444 70%, #000000 30%);
    font-size: 16px;
    flex-shrink: 0;
}

.validation-summary__text {
    font-size: 12px;
    color: color-mix(in srgb, #ef4444 65%, #000000 35%);
    line-height: 1.4;
    flex: 1;
}

/* Close button for validation summary */
.validation-summary__close {
    background: transparent;
    border: none;
    color: color-mix(in srgb, #ef4444 65%, #000000 35%);
    font-size: 16px;
    cursor: pointer;
    padding: 0 4px;
    margin-left: auto;
    flex-shrink: 0;
    opacity: 0.7;
    transition: opacity 0.15s ease;
}

    .validation-summary__close:hover {
        opacity: 1;
    }

.validation-summary--success .validation-summary__close {
    color: color-mix(in srgb, #10b981 75%, #000000 25%);
}

/* Success variant of validation summary */
.validation-summary--success {
    background: color-mix(in srgb, #ffffff 94%, #10b981 6%);
    border-color: color-mix(in srgb, #10b981 35%, #ffffff 65%);
}

    .validation-summary--success .validation-summary__icon {
        color: color-mix(in srgb, #10b981 75%, #000000 25%);
    }

    .validation-summary--success .validation-summary__text {
        color: color-mix(in srgb, #10b981 70%, #000000 30%);
    }

@keyframes fadeInSummary {
    from {
        opacity: 0;
        transform: translateY(-4px);
    }

    to {
        opacity: 1;
        transform: translateY(0);
    }
}

/* Hide summary when no errors */
.validation-summary:empty,
.validation-summary:not(.is-visible) {
    display: none;
}

